// Type definitions
export interface BlockContext {
	name: string;
	clientId?: string;
	attributes?: Record< string, any >;
	innerBlocks?: BlockContext[];
}

// Define all suggestion IDs as a const object for type inference
export const SUGGESTION_IDS = {
	CUSTOMIZE_COLORS: 'customize-colors',
	CHOOSE_NEW_FONTS: 'choose-new-fonts',
	EDIT_LINK: 'edit-link',
	SWAP_COLUMNS: 'columns-within-group',
	ADD_COLUMN: 'add-column',
	TRANSLATE: 'translate',
	CHANGE_TONE: 'change-tone',
	CHECK_GRAMMAR: 'check-grammar',
	GENERATE_IMAGE: 'generate-image',
	EDIT_IMAGE: 'edit-image',
	REMOVE_IMAGE_BACKGROUND: 'remove-image-background',
	CHANGE_PAGE_LAYOUT: 'change-page-layout',
	EDIT_PAGES: 'edit-pages',
	WHAT_ELSE_CAN_YOU_DO: 'what-else-can-i-do',
	CHANGE_NUMBER_OF_POSTS: 'change-number-of-posts',
	ORDER_POSTS: 'order-posts',
} as const;

export type SuggestionId =
	( typeof SUGGESTION_IDS )[ keyof typeof SUGGESTION_IDS ];

// Base suggestion interface without block-specific logic
interface BaseSuggestion {
	id: SuggestionId;
	label: string;
	action?: ( block: BlockContext ) => boolean | Promise< boolean >;
	prompt: string | ( ( block: BlockContext ) => string );
	condition?: ( block: BlockContext ) => boolean;
}

// Injected server-side as a bare `const` global (not on `window`).
declare const agentsManagerData: {
	jetpackAiSidebar?: { enabled?: boolean };
};

// Whether the Jetpack AI Sidebar is enabled; when it is, it owns block
// transformations and image suggestions, so Big Sky defers those to it.
function isJetpackAIEnabled(): boolean {
	return (
		typeof agentsManagerData !== 'undefined' &&
		agentsManagerData?.jetpackAiSidebar?.enabled === true
	);
}

