// Helper function that validates all suggestion IDs are used in the mappings
function createCompleteBlockTypeMappings<
	T extends Record< string, readonly SuggestionId[] >,
>(
	mappings: T &
		( SuggestionId extends T[ keyof T ][ number ]
			? unknown
			: { ERROR: 'Not all suggestion IDs are used in mappings' } )
): T {
	return mappings;
}

// Block type mappings - '*' is for global suggestions (shown when no block is selected)
const blockTypeMappings = createCompleteBlockTypeMappings( {
	'*': [
		SUGGESTION_IDS.CUSTOMIZE_COLORS,
		SUGGESTION_IDS.CHANGE_PAGE_LAYOUT,
		SUGGESTION_IDS.CHOOSE_NEW_FONTS,
		SUGGESTION_IDS.EDIT_PAGES,
		SUGGESTION_IDS.WHAT_ELSE_CAN_YOU_DO,
	],
	'core/button': [ SUGGESTION_IDS.EDIT_LINK ],
	'core/query': [
		SUGGESTION_IDS.CHANGE_NUMBER_OF_POSTS,
		SUGGESTION_IDS.ORDER_POSTS,
	],
	'core/group': [
		SUGGESTION_IDS.ADD_COLUMN,
		SUGGESTION_IDS.SWAP_COLUMNS,
		SUGGESTION_IDS.CHANGE_NUMBER_OF_POSTS,
		SUGGESTION_IDS.ORDER_POSTS,
	],
	'core/paragraph': [
		SUGGESTION_IDS.TRANSLATE,
		SUGGESTION_IDS.CHANGE_TONE,
		SUGGESTION_IDS.CHECK_GRAMMAR,
	],
	'core/heading': [
		SUGGESTION_IDS.TRANSLATE,
		SUGGESTION_IDS.CHANGE_TONE,
		SUGGESTION_IDS.CHECK_GRAMMAR,
	],
	'core/image': [
		SUGGESTION_IDS.GENERATE_IMAGE,
		SUGGESTION_IDS.EDIT_IMAGE,
		SUGGESTION_IDS.REMOVE_IMAGE_BACKGROUND,
	],
} as const );

// Type for block type mapping keys
type BlockTypeMappingKey = keyof typeof blockTypeMappings;

// Algorithm functions
function filterSuggestionsForBlock(
	block: BlockContext | null
): BaseSuggestion[] {
	const applicableSuggestions: BaseSuggestion[] = [];

	// Get the appropriate mappings based on block type
	const mappingKey = block === null ? '*' : block.name;
	const matchingSuggestionIds =
		blockTypeMappings[ mappingKey as BlockTypeMappingKey ] || [];

	for ( const suggestionId of matchingSuggestionIds ) {
		const suggestion = suggestions[ suggestionId ];
		if (
			block !== null &&
			suggestion.condition &&
			! suggestion.condition( block )
		) {
			// Skip if there's a condition and it's not met
			continue;
		}
		applicableSuggestions.push( { ...suggestion, id: suggestionId } );
	}

	return applicableSuggestions;
}

const processPrompt = (
	suggestion: BaseSuggestion,
	block: BlockContext | null
): Suggestion => {
	let prompt: string | undefined;
	let action: ( () => boolean | Promise< boolean > ) | undefined;

	if ( typeof suggestion.prompt === 'function' ) {
		if ( block !== null ) {
			prompt = suggestion.prompt( block );
		}
	} else {
		prompt = suggestion.prompt;
	}

	if ( suggestion.action && block ) {
		const suggestionAction = suggestion.action;
		action = () => suggestionAction( block );
	}

	return {
		id: suggestion.id,
		label: suggestion.label,
		...( action && { action } ),
		...( prompt && { prompt } ),
	};
};

/**
 * Filters suggestions based on whether the current theme is Assembler.
 * Non-Assembler themes only show page layout and page editing suggestions.
 *
 * @param allSuggestions - Array of suggestions to filter
 * @return Filtered array of suggestions
 */
export const filterSuggestionsForTheme = (
	allSuggestions: Suggestion[]
): Suggestion[] => {
	const theme = selectFromCoreStore( coreStore ).getCurrentTheme();
	// Stylesheets names are different in different environments
	const isAssemblerTheme =
		theme?.stylesheet === 'pub/assembler' || // Simple
		theme?.stylesheet === 'assembler-wpcom' || // Atomic
		theme?.stylesheet === 'assembler'; // localhost/JN

	if ( isAssemblerTheme ) {
		return allSuggestions;
	}

	return allSuggestions.filter(
		( suggestion ) =>
			suggestion.id !== SUGGESTION_IDS.CHANGE_PAGE_LAYOUT &&
			suggestion.id !== SUGGESTION_IDS.EDIT_PAGES
	);
};

export const getEmptyViewSuggestions = (): Suggestion[] => {
	const allSuggestions = [
		SUGGESTION_IDS.CUSTOMIZE_COLORS,
		SUGGESTION_IDS.CHANGE_PAGE_LAYOUT,
		SUGGESTION_IDS.CHOOSE_NEW_FONTS,
		SUGGESTION_IDS.EDIT_PAGES,
		SUGGESTION_IDS.WHAT_ELSE_CAN_YOU_DO,
	].map( ( id ) => {
		return processPrompt( { ...suggestions[ id ], id }, null );
	} );

	return filterSuggestionsForTheme( allSuggestions );
};

/**
 * Helper function to process all filtered suggestions
 * @param block the block to filter
 * @param count the count of suggestions to return. If 0, all the matching suggestions will be returned.
 * @return the processed suggestions
 */
export const getSuggestions = (
	block: BlockContext | null,
	count: number = 0
): Suggestion[] => {
	const filtered = filterSuggestionsForBlock( block );
	const processed = filtered.map( ( suggestion ) =>
		processPrompt( suggestion, block )
	);

	if ( count > 0 && processed.length > count ) {
		// Fisher-Yates shuffle for first 'count' elements
		const shuffled = [ ...processed ];
		for ( let i = 0; i < count; i++ ) {
			// eslint-disable-next-line no-restricted-syntax
			const j = Math.floor( Math.random() * ( shuffled.length - i ) ) + i;
			[ shuffled[ i ], shuffled[ j ] ] = [ shuffled[ j ], shuffled[ i ] ];
		}
		return shuffled.slice( 0, count );
	}

	return processed;
};
