/**
 * WordPress dependencies
 */
import { createBlock, parse, serialize } from '@wordpress/blocks';
import { dispatch, select } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as coreStore } from '@wordpress/core-data';
import { store as editorStore } from '@wordpress/editor';
import { recreateBlock } from '@utils/block-utils';
import {
	isTemplatePartPatternSlug,
	TemplatePartPatternSlug,
	TemplatePartSlug,
} from '@utils/template-parts';
import setDelay from '@utils/set-delay';
import { scrollToBlock } from '@utils/block-dom';
import { unlock } from '@utils/lock-unlock';
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';
import { STORE_NAME as aiStore } from '@store/constants.js';
import { isValidStoreSite } from '@utils/store-site';

/**
 * Create a dummy section block for placeholder content
 *
 * @param {Object}  options           - Options for creating the dummy section
 * @param {boolean} options.isEmpty   - Whether the section is empty
 * @param {string}  options.className - Additional CSS class name
 * @return {Object} A dummy section block
 */
function createDummySection( { isEmpty = true, className = '' } = {} ) {
	const DUMMY_SECTION_CLASSNAMES = 'big-sky__dummy-section alignfull';
	return createBlock(
		'core/group',
		{
			className: `${ DUMMY_SECTION_CLASSNAMES } ${
				isEmpty ? 'big-sky__is-empty-dummy' : ''
			} ${ className }`,
		},
		[
			createBlock( 'core/paragraph', {
				placeholder: ' ',
			} ),
		]
	);
}

/**
 * Get the template part client ID by slug
 *
 * @param {string} slug - Template part slug
 * @return {string|undefined} Template part client ID or undefined
 */
function getTemplatePartClientID( slug ) {
	const blockEditorSelect = select( blockEditorStore );
	const templatePartClientIds =
		blockEditorSelect.getBlocksByName( 'core/template-part' );

	if ( ! templatePartClientIds ) {
		return;
	}

	return templatePartClientIds.find( ( clientId ) => {
		const block = blockEditorSelect.getBlock( clientId );
		return block?.attributes?.slug === slug;
	} );
}

/**
 * Get the root blocks of the content area (section between header and footer).
 * Can be used outside of React hooks - reads from the block editor store directly.
 *
 * @return {Array} Array of block objects in the content area
 */
export function getRootBlocksOfContent() {
	const blockEditorSelect = select( blockEditorStore );
	const getSectionRootClientId =
		unlock( blockEditorSelect ).getSectionRootClientId;
	const getBlocks = blockEditorSelect.getBlocks;
	return getBlocks( getSectionRootClientId() );
}

/**
 * Insert dummy sections into the canvas
 * This is a standalone version that works in Redux action context
 *
 * @param {Object}  options                      - Options for inserting dummy sections
 * @param {number}  options.count                - Number of dummy sections to insert
 * @param {boolean} options.replaceTemplateParts - Whether to replace template parts
 */
export async function insertDummySections( {
	count,
	replaceTemplateParts = true,
} ) {
	if ( count <= 0 ) {
		return;
	}

	const blockEditorSelect = select( blockEditorStore );
	const blockEditorDispatch = dispatch( blockEditorStore );

	const getSectionRootClientId =
		unlock( blockEditorSelect ).getSectionRootClientId;
	const getBlocks = blockEditorSelect.getBlocks;
	const replaceInnerBlocks = blockEditorDispatch.replaceInnerBlocks;
	const __unstableMarkNextChangeAsNotPersistent =
		blockEditorDispatch.__unstableMarkNextChangeAsNotPersistent;

	// Create dummy sections based on the wireframe section count
	const dummySections = Array.from( {
		length: count,
	} ).map( createDummySection );

	const contentBlockClientID = getSectionRootClientId();
	let headerTemplatePartClientID;
	if ( isValidStoreSite() ) {
		headerTemplatePartClientID = getTemplatePartClientID(
			TemplatePartSlug.Header
		);
	} else {
		headerTemplatePartClientID = getTemplatePartClientID(
			TemplatePartSlug.HeaderHero
		);
	}
	const footerTemplatePartClientID = getTemplatePartClientID(
		TemplatePartSlug.Footer
	);

	if ( replaceTemplateParts && headerTemplatePartClientID ) {
		const currentHeaderBlocks = getBlocks( headerTemplatePartClientID );
		const hasRemotePatternId =
			currentHeaderBlocks?.[ 0 ]?.innerBlocks?.[ 0 ]?.attributes?.metadata
				?.remotePatternId;
		if ( ! hasRemotePatternId ) {
			const dummySection = dummySections.shift();
			__unstableMarkNextChangeAsNotPersistent();
			replaceInnerBlocks( headerTemplatePartClientID, [ dummySection ] );
		}
	} else {
		// force a shift to remove a dummy section here
		// it's possible the header hero template part doesn't exist yet, if it's the first ever build or if the page template is not the hero page template
		dummySections.shift();
	}

	if ( replaceTemplateParts && footerTemplatePartClientID ) {
		const currentFooterBlocks = getBlocks( footerTemplatePartClientID );
		const hasRemotePatternId =
			currentFooterBlocks?.[ 0 ]?.innerBlocks?.[ 0 ]?.attributes?.metadata
				?.remotePatternId;
		if ( ! hasRemotePatternId ) {
			const dummySection = dummySections.shift();
			__unstableMarkNextChangeAsNotPersistent();
			replaceInnerBlocks( footerTemplatePartClientID, [ dummySection ] );
		}
	}

	const currentContentBlocks = getBlocks( contentBlockClientID );
	const hasRemotePatternId =
		currentContentBlocks?.[ 0 ]?.innerBlocks?.[ 0 ]?.attributes?.metadata
			?.remotePatternId;
	if ( ! hasRemotePatternId ) {
		__unstableMarkNextChangeAsNotPersistent();
		replaceInnerBlocks( contentBlockClientID, dummySections );
	}
}

/**
 * Blank the header and footer template parts at the start of a build.
 *
 * Edits the template-part *entity* records (the same persistent mechanism the
 * compose step uses via `editEntityRecord`) so the editor renders a clean page
 * during the structure phase instead of the previous site's saved header and
 * footer. Block-editor-level changes are reverted when the entity re-syncs from
 * its saved data; entity edits stick. Compose later replaces these with the
 * real composed patterns.
 *
 * Because the blank is a persistent entity edit, it must be reverted if the
 * build fails — otherwise the header/footer entities stay dirty and empty, and
 * the next save persists the blanks over the real header/footer. This function
 * captures each part's original content and returns a callback that restores
 * it; the caller invokes it when the build errors out. On a successful build
 * compose overwrites the parts, so the callback is never needed.
 *
 * @return {Promise<Function>} Resolves to a callback that restores the original
 *                             header/footer template parts.
 */
export async function blankBuildTemplateParts() {
	const coreSelect = select( coreStore );
	const theme = coreSelect.getCurrentTheme();
	if ( ! theme ) {
		return () => {};
	}
	const { editEntityRecord } = dispatch( coreStore );

	// Clear whichever header part the active template uses, plus the footer.
	const slugs = isValidStoreSite()
		? [ TemplatePartSlug.Header, TemplatePartSlug.Footer ]
		: [
				TemplatePartSlug.HeaderHero,
				TemplatePartSlug.Header,
				TemplatePartSlug.Footer,
		  ];

	// Remember each part's current content so a failed build can put it back.
	const originals = [];

	for ( const slug of slugs ) {
		const templatePartId = `${ theme.stylesheet }//${ slug }`;
		const record = coreSelect.getEntityRecord(
			'postType',
			'wp_template_part',
			templatePartId
		);
		if ( ! record ) {
			continue;
		}

		const edited = coreSelect.getEditedEntityRecord(
			'postType',
			'wp_template_part',
			templatePartId
		);
		const content =
			typeof edited.content === 'string'
				? edited.content
				: edited.content?.raw ?? '';
		originals.push( { templatePartId, content } );

		await editEntityRecord(
			'postType',
			'wp_template_part',
			templatePartId,
			{
				blocks: [],
				content: serialize( [] ),
			}
		);
	}

	return async function restoreBlankedTemplateParts() {
		for ( const { templatePartId, content } of originals ) {
			await editEntityRecord(
				'postType',
				'wp_template_part',
				templatePartId,
				{
					blocks: parse( content ),
					content,
				}
			);
		}
	};
}

/**
 * Split patterns into header, headerHero, body, and footer patterns
 *
 * @param {Array} patterns - Array of pattern objects
 * @return {Object} Object with headerPattern, headerHeroPattern, bodyPatterns, footerPattern
 */
export function splitPatterns( patterns ) {
	const headerPattern = patterns.find(
		( p ) => p.pattern.category === TemplatePartPatternSlug.Header
	);
	const headerHeroPattern = patterns.find(
		( p ) => p.pattern.category === TemplatePartPatternSlug.HeaderHero
	);
	const footerPattern = patterns.find(
		( p ) => p.pattern.category === TemplatePartPatternSlug.Footer
	);
	const bodyPatterns = patterns.filter(
		( p ) => ! isTemplatePartPatternSlug( p.pattern.category )
	);

	return {
		headerPattern,
		headerHeroPattern,
		bodyPatterns,
		footerPattern,
	};
}

/**
 * Get the container client ID for a pattern based on its category
 *
 * @param {Object} pattern - Pattern object with category
 * @return {string} Container client ID
 */
function getContainerClientID( pattern ) {
	if ( pattern?.category === TemplatePartPatternSlug.Header ) {
		return getTemplatePartClientID( TemplatePartSlug.Header );
	}

	if (
		pattern?.category === TemplatePartPatternSlug.HeaderHero &&
		! isValidStoreSite()
	) {
		return getTemplatePartClientID( TemplatePartSlug.HeaderHero );
	}

	if ( pattern?.category === TemplatePartPatternSlug.Footer ) {
		return getTemplatePartClientID( TemplatePartSlug.Footer );
	}

	const blockEditorSelect = select( blockEditorStore );
	const getSectionRootClientId =
		unlock( blockEditorSelect ).getSectionRootClientId;
	return getSectionRootClientId();
}

/**
 * Add blocks to a dummy section to create a skeleton structure
 *
 * @param {Object}   rootPatternBlock                        - Root pattern block
 * @param {string}   dummySectionClientId                    - Dummy section client ID
 * @param {Function} replaceInnerBlocks                      - Function to replace inner blocks
 * @param {Function} updateBlockAttributes                   - Function to update block attributes
 * @param {Function} __unstableMarkNextChangeAsNotPersistent - Function to mark change as not persistent
 */
function addBlocksToDummySection(
	rootPatternBlock,
	dummySectionClientId,
	replaceInnerBlocks,
	updateBlockAttributes,
	__unstableMarkNextChangeAsNotPersistent
) {
	const DUMMY_SECTION_CLASSNAMES = 'big-sky__dummy-section alignfull';

	if (
		! isTemplatePartPatternSlug(
			rootPatternBlock.attributes?.metadata?.patternCategory
		)
	) {
		__unstableMarkNextChangeAsNotPersistent();
	}

	replaceInnerBlocks( dummySectionClientId, [ rootPatternBlock ], false );

	// Remove the background color style from the rootPattern block in the skeleton
	__unstableMarkNextChangeAsNotPersistent();
	updateBlockAttributes( rootPatternBlock.clientId, {
		style: {
			...rootPatternBlock.attributes.style,
			color: {
				background: undefined,
			},
		},
	} );
	__unstableMarkNextChangeAsNotPersistent();
	updateBlockAttributes( dummySectionClientId, {
		className: `${ DUMMY_SECTION_CLASSNAMES } big-sky__has-dummy-blocks `,
	} );
}

/**
 * Add pattern skeleton to dummy section
 *
 * @param {Object} pattern - Pattern object
 * @param {number} index   - Index of the pattern
 */
export function addPatternSkeleton( pattern, index ) {
	const blockEditorSelect = select( blockEditorStore );
	const blockEditorDispatch = dispatch( blockEditorStore );
	const getBlocks = blockEditorSelect.getBlocks;
	const replaceInnerBlocks = blockEditorDispatch.replaceInnerBlocks;
	const updateBlockAttributes = blockEditorDispatch.updateBlockAttributes;
	const __unstableMarkNextChangeAsNotPersistent =
		blockEditorDispatch.__unstableMarkNextChangeAsNotPersistent;

	const rootPatternBlock = recreateBlock( pattern.blocks[ 0 ] );
	const containerClientID = getContainerClientID( pattern );

	const dummySectionClientIds = getBlocks( containerClientID ).map(
		( block ) => block.clientId
	);

	if ( dummySectionClientIds[ index ] ) {
		addBlocksToDummySection(
			rootPatternBlock,
			dummySectionClientIds[ index ],
			replaceInnerBlocks,
			updateBlockAttributes,
			__unstableMarkNextChangeAsNotPersistent
		);
	}
}

/**
 * Add pattern to canvas with animation
 *
 * @param {Object}  pattern - Pattern object
 * @param {number}  index   - Index of the pattern
 * @param {boolean} animate - Whether to animate the pattern
 */
export async function addPatternToCanvas( pattern, index, animate ) {
	const blockEditorSelect = select( blockEditorStore );
	const blockEditorDispatch = dispatch( blockEditorStore );
	const editorDispatch = dispatch( editorStore );
	const getBlocks = blockEditorSelect.getBlocks;
	const replaceInnerBlocks = blockEditorDispatch.replaceInnerBlocks;
	const __unstableMarkNextChangeAsNotPersistent =
		blockEditorDispatch.__unstableMarkNextChangeAsNotPersistent;
	const replaceBlock = editorDispatch.replaceBlock;

	const rootPatternBlock = recreateBlock( pattern.blocks[ 0 ] );

	function getClientIdAtIndex() {
		const containerClientID = getContainerClientID( pattern );
		const dummySectionClientIds = getBlocks( containerClientID ).map(
			( block ) => block.clientId
		);
		return dummySectionClientIds[ index ];
	}

	// Update support for background color
	rootPatternBlock.supports = {
		color: { background: true },
		...rootPatternBlock.supports,
	};

	const targetClientId = getClientIdAtIndex();
	if ( ! targetClientId ) {
		return;
	}

	if ( animate ) {
		// Start scrolling to the right location before we insert the block
		scrollToBlock( targetClientId, 'center' );

		// Let the scroll get there before inserting
		await setDelay( 500 );
	}

	// Replace the dummy pattern with the final pattern
	// Template-part patterns use replaceInnerBlocks on the container so the
	// change applies inside the template part. replaceBlock does not reliably
	// replace blocks inside a template part.
	// - Store: header and footer use replaceInnerBlocks.
	// - Non-store: header-hero and footer use replaceInnerBlocks.
	// - Store header-hero lives in section root, so it uses replaceBlock.
	const isStore = isValidStoreSite();
	const useReplaceInnerBlocks =
		pattern.category === TemplatePartPatternSlug.Header ||
		pattern.category === TemplatePartPatternSlug.Footer ||
		( pattern.category === TemplatePartPatternSlug.HeaderHero &&
			! isStore );

	if ( useReplaceInnerBlocks ) {
		if ( animate ) {
			__unstableMarkNextChangeAsNotPersistent();
		}
		const containerID = getContainerClientID( pattern );
		replaceInnerBlocks( containerID, [ rootPatternBlock ], false );
	} else {
		if ( animate ) {
			__unstableMarkNextChangeAsNotPersistent();
		}
		replaceBlock( targetClientId, rootPatternBlock );
	}

	if ( animate ) {
		await setDelay( 750 );
	}
}

/**
 * Find navigation block in blocks array
 *
 * @param {Array} blocks - Array of blocks to search
 * @return {Object|undefined} Navigation block or undefined
 */
function findNavigationBlock( blocks ) {
	for ( const block of blocks ) {
		if ( block.name === 'core/navigation' ) {
			return block;
		}
		if ( block.innerBlocks ) {
			const innerBlock = findNavigationBlock( block.innerBlocks );
			if ( innerBlock ) {
				return innerBlock;
			}
		}
	}
}

/**
 * Add patterns to canvas with animations
 *
 * @param {Array}  patternsToAdd          - Array of pattern objects to add to canvas
 * @param {Object} options                - Additional options
 * @param {Object} options.navigationMenu - Navigation menu object (optional)
 */
export async function addPatternsToCanvas( patternsToAdd, options = {} ) {
	const { navigationMenu, animate = true } = options;
	try {
		// Access WordPress data stores
		const coreDispatch = dispatch( coreStore );

		// Get delay settings from store
		const delaySettings = select( aiStore ).getDelaySettings?.() || {
			onboarding: { afterBlockProcessed: 1000 },
		};

		// Get functions
		const editEntityRecord = coreDispatch.editEntityRecord;

		// Get selectors from core store
		const coreSelect = select( coreStore );
		const getCurrentTheme = coreSelect.getCurrentTheme;
		const getEntityRecord = coreSelect.getEntityRecord;

		// Helper to replace template part
		const replaceTemplatePart = async ( templatePartName, blocks ) => {
			const theme = getCurrentTheme();
			if ( ! theme ) return;
			const templatePartId = `${ theme.stylesheet }//${ templatePartName }`;
			const record = getEntityRecord(
				'postType',
				'wp_template_part',
				templatePartId
			);
			if ( ! record ) return;
			await editEntityRecord(
				'postType',
				'wp_template_part',
				templatePartId,
				{ blocks, content: serialize( blocks ) }
			);
		};

		// Split patterns
		const {
			headerPattern,
			headerHeroPattern,
			bodyPatterns,
			footerPattern,
		} = splitPatterns( patternsToAdd );

		// Add pattern skeletons (only if animating)
		if ( animate ) {
			if ( isValidStoreSite() && headerPattern ) {
				addPatternSkeleton( headerPattern.pattern, 0 );
			}
			if ( headerHeroPattern ) {
				addPatternSkeleton( headerHeroPattern.pattern, 0 );
			}
			for ( let i = 0; i < bodyPatterns.length; i++ ) {
				if ( bodyPatterns[ i ] ) {
					addPatternSkeleton(
						bodyPatterns[ i ].pattern,
						isValidStoreSite() ? i + 1 : i
					);
				}
			}
			if ( footerPattern ) {
				addPatternSkeleton( footerPattern.pattern, 0 );
			}
		}

		// Replace header template part
		if ( headerPattern ) {
			// Find navigation block and update it if navigationMenu is provided
			const navBlock = findNavigationBlock(
				headerPattern.pattern.blocks
			);
			if ( navBlock && navigationMenu ) {
				navBlock.attributes.ref = navigationMenu.id;
				// Note: We can't update block attributes here since blocks haven't been inserted yet
				// The attributes will be set when the template part is replaced
			}

			if ( isValidStoreSite() ) {
				await addPatternToCanvas( headerPattern.pattern, 0, animate );
			} else {
				await replaceTemplatePart( TemplatePartSlug.Header, [
					...headerPattern.pattern?.blocks,
				] );
			}
		}

		// Add header hero pattern with animation
		if ( headerHeroPattern ) {
			// Delay between each section sliding in (only if animating)
			if ( animate ) {
				await setDelay( delaySettings.onboarding.afterBlockProcessed );
			}

			await addPatternToCanvas( headerHeroPattern.pattern, 0, animate );
		}

		// Add body patterns with animations
		for ( let i = 0; i < bodyPatterns.length; i++ ) {
			const { pattern } = bodyPatterns[ i ];

			// Delay between each section sliding in (only if animating)
			if ( animate ) {
				await setDelay( delaySettings.onboarding.afterBlockProcessed );
			}

			await addPatternToCanvas(
				pattern,
				isValidStoreSite() ? i + 1 : i,
				animate
			);
		}

		// Add footer pattern with animation
		if ( footerPattern ) {
			// Find navigation block and update it if navigationMenu is provided
			const navBlock = findNavigationBlock(
				footerPattern.pattern.blocks
			);
			if ( navBlock && navigationMenu ) {
				navBlock.attributes.ref = navigationMenu.id;
			}

			if ( animate ) {
				await setDelay( delaySettings.onboarding.afterBlockProcessed );
			}

			await addPatternToCanvas( footerPattern.pattern, 0, animate );
		}

		// Scroll to top (only if animating)
		if ( animate ) {
			await setDelay( delaySettings.onboarding.afterBlockProcessed );
			const { canvasiFrameWindow } = getCanvasIframeElements();
			canvasiFrameWindow?.scrollTo( { top: 0, behavior: 'smooth' } );
		}
	} catch ( error ) {
		console.error(
			'❌ Error adding patterns to canvas with animations:',
			error
		);
		throw error;
	}
}
