/**
 * Internal dependencies
 */
import { PROCESSING_FEATURES } from './constants.js';

/**
 * Get all available block processing state features.
 * @return {string[]} Array of all available processing features
 */
export const getAllProcessingFeatures = () =>
	Object.values( PROCESSING_FEATURES );

/**
 * Check if a processing feature is valid
 * @param {string} feature Processing feature to check
 * @return {boolean} Whether the processing feature is valid
 */
export const isValidProcessingFeature = ( feature ) =>
	getAllProcessingFeatures().includes( feature );
