/**
 * Internal dependencies
 */
import { requestJetpackToken } from '@utils/request-jetpack-token.ts';
import log from '@utils/log-debug.js';

export const generateImage =
	( {
		model,
		prompt,
		n = 1,
		size,
		response_format = 'url',
		output_format = 'png',
		output_compression = 90,
		doRetry = true,
		quality = 'low',
		remove_background = true,
		image = null,
		background = 'auto',
	} ) =>
	async ( { select, dispatch } ) => {
		try {
			const jetpackToken = await requestJetpackToken();
			if ( ! jetpackToken ) {
				return;
			}
			const imageGenerationUrl =
				'https://public-api.wordpress.com/wpcom/v2/jetpack-ai-image';

			const isDevMode = window.bigSkyInitialState?.isDevMode ?? false;

			const params = {
				model,
				prompt,
				n,
				size,
				response_format,
				remove_background,
				output_format,
				output_compression,
				feature: isDevMode ? 'big-sky-dev' : 'big-sky',
				session_id: select.getSessionId(),
				quality,
				background,
			};

			let requestBody;
			const headers = {
				Authorization: `Bearer ${ jetpackToken.token }`,
			};

			if ( image && image instanceof File ) {
				// Use FormData for image editing - the API expects file uploads as multipart/form-data
				const formData = new FormData();
				Object.entries( params ).forEach( ( [ key, value ] ) => {
					if ( value !== undefined ) {
						formData.append( key, value );
					}
				} );
				formData.append( 'image', image );

				requestBody = formData;
				// Don't set Content-Type for FormData, let the browser set it with boundary
			} else {
				// Use JSON for regular image generation
				requestBody = JSON.stringify( params );
				headers[ 'Content-Type' ] = 'application/json';
			}

			const request = await fetch( imageGenerationUrl, {
				method: 'POST',
				headers,
				body: requestBody,
			} );

			if ( request.status >= 300 ) {
				// retry once with a new token
				if ( doRetry ) {
					return dispatch.generateImage( {
						model,
						prompt,
						n,
						size,
						response_format,
						output_format,
						output_compression,
						doRetry: false,
						quality,
						image,
						background,
					} );
				}

				log.error( 'Error calling Image Generation API:', request );
				return null;
			}
			const response = await request.json();

			return response;
		} catch ( e ) {
			// retry once with a new token
			if ( doRetry ) {
				return dispatch.generateImage( {
					model,
					prompt,
					n,
					size,
					response_format,
					output_format,
					output_compression,
					doRetry: false,
					quality,
					image,
					background,
				} );
			}

			log.error( 'Error calling Image Generation API:', e );
			return null;
		}
	};
