/**
 * WordPress dependencies
 */
import { useCallback, useEffect, useRef } from '@wordpress/element';
import { useDispatch, useSelect } from '@wordpress/data';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import { recordTracksEvent } from '@utils/tracks';

// Track if popstate listener is already attached
let popstateListenerAttached = false;
let latestHandlerRef = null;

export function useRouting() {
	const currentStep = useSelect( ( select ) =>
		select( aiStore ).getAiStep()
	);

	const { setAiStep: setAiStepInStore, setHeaderSectionIsReady } =
		useDispatch( aiStore );

	const getAiStep = useCallback( () => {
		return currentStep;
	}, [ currentStep ] );

	const setAiStep = useCallback(
		( newStep, forceToHistory = false ) => {
			if ( currentStep !== newStep || forceToHistory ) {
				setAiStepInStore( newStep, currentStep );
				const url = new URL( window.location.href );
				url.searchParams.set( 'ai-step', newStep );

				if ( forceToHistory ) {
					window.history.replaceState( { aiStep: newStep }, '', url );
				} else {
					window.history.pushState( { aiStep: newStep }, '', url );
				}
			}
		},
		[ currentStep, setAiStepInStore ]
	);

	const handleUrlChange = useCallback( () => {
		const url = new URL( window.location.href );
		const aiStep = url.searchParams.get( 'ai-step' );
		const aiOpen = url.searchParams.get( 'ai-open' );

		// Check if AI editor should be opened directly
		if ( aiOpen === 'true' ) {
			recordTracksEvent( 'ai_editor_menu_opened' );

			// Clear the query parameter to prevent re-opening
			url.searchParams.delete( 'ai-open' );
			window.history.replaceState( {}, '', url );
		}

		const normalizedUrlStep = aiStep || null;

		// Always sync store state with URL when URL changes (browser navigation)
		// Always dispatch update to ensure React components re-render
		if (
			normalizedUrlStep !== currentStep &&
			normalizedUrlStep === 'spec'
		) {
			setHeaderSectionIsReady( false );
		}
		setAiStepInStore( normalizedUrlStep, currentStep );
	}, [ currentStep, setAiStepInStore, setHeaderSectionIsReady ] );

	// Keep handler ref updated
	const handlerRef = useRef( handleUrlChange );
	useEffect( () => {
		handlerRef.current = handleUrlChange;
		latestHandlerRef = handleUrlChange;
	}, [ handleUrlChange ] );

	useEffect( () => {
		handleUrlChange();
		if ( ! popstateListenerAttached ) {
			const wrappedHandler = () => {
				if ( latestHandlerRef ) {
					latestHandlerRef();
				}
			};
			window.addEventListener( 'popstate', wrappedHandler );
			popstateListenerAttached = true;
		}
	}, [ handleUrlChange ] );

	return {
		setAiStep,
		getAiStep,
	};
}
