/**
 * Internal dependencies
 */
import { resetAllBlockProcessingStates } from '@utils/block-processing-state';

/**
 * Store action to reset all block processing states
 * This is useful when aborting operations or cleaning up after errors
 * Delegates to the shared utility function for consistency
 *
 * @return {Function} Thunk action
 */
export const resetAllBlockIsProcessing = () => () => {
	resetAllBlockProcessingStates();
};
