/**
 * Helper shared by the editor context providers that feed
 * the page-design agent. Serializes the live core/post-content body to Gutenberg
 * block markup so the agent reads the current layout (wrappers + inner blocks +
 * real image URLs/IDs/alt) from live editor state rather than the saved,
 * possibly-stale post_content.
 */
import { serialize } from '@wordpress/blocks';

/** A minimal editor-block shape: name, clientId, and recursive inner blocks. */
export interface PostContentBlockLike {
	name?: string;
	clientId?: string;
	innerBlocks?: PostContentBlockLike[];
}

/**
 * Depth-first search for the first core/post-content block, descending into
 * controlled inner blocks via `getBlocks( clientId )` when a block does not carry
 * them inline.
 *
 * @param getBlocks  Block-editor `getBlocks` selector.
 * @param rootBlocks Blocks to search from; defaults to `getBlocks()`.
 * @return The core/post-content block, or null when there is none.
 */
export function findPostContentBlock(
	getBlocks: ( clientId?: string ) => PostContentBlockLike[],
	rootBlocks?: PostContentBlockLike[]
): PostContentBlockLike | null {
	const search = (
		candidates: PostContentBlockLike[]
	): PostContentBlockLike | null => {
		for ( const block of candidates || [] ) {
			if ( block?.name === 'core/post-content' ) {
				return block;
			}
			let inner: PostContentBlockLike[];
			if ( block?.innerBlocks?.length ) {
				inner = block.innerBlocks;
			} else if ( block?.clientId ) {
				inner = getBlocks( block.clientId );
			} else {
				inner = [];
			}
			const found = inner?.length ? search( inner ) : null;
			if ( found ) {
				return found;
			}
		}
		return null;
	};

	return search( rootBlocks ?? getBlocks() ?? [] );
}

/**
 * Serialize the live core/post-content body to Gutenberg block markup.
 *
 * @param getBlocks  Block-editor `getBlocks` selector.
 * @param rootBlocks Blocks to search from; defaults to `getBlocks()`.
 * @return Serialized post-content body markup, or '' when unavailable.
 */
export function serializePostContentBody(
	getBlocks: ( clientId?: string ) => PostContentBlockLike[],
	rootBlocks?: PostContentBlockLike[]
): string {
	try {
		const postContent = findPostContentBlock( getBlocks, rootBlocks );
		if ( ! postContent?.clientId ) {
			return '';
		}
		const body = getBlocks( postContent.clientId ) || [];
		return body.length
			? serialize( body as Parameters< typeof serialize >[ 0 ] )
			: '';
	} catch {
		return '';
	}
}
