/**
 * WordPress dependencies
 */
import { useSelect } from '@wordpress/data';
import { useEffect, useRef, useState } from '@wordpress/element';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import { getCanvasIframeElements } from '@utils/canvas-iframe-elements';

/**
 * Class that blurs the page's copy while the agent replaces it.
 */
const MASK_CLASS = 'big-sky__blueprint-copy-pending';

/**
 * Never leave the page masked. If the rewrite dies somewhere we cannot see —
 * a dropped connection, a turn that ends without applying anything — the
 * customer is left looking at a blurred site with no way to clear it. Better a
 * premature reveal of the blueprint's copy than a page that looks broken.
 */
const MASK_TIMEOUT_MS = 90000;

/**
 * Blur the blueprint's copy while it is being rewritten, then reveal the result.
 *
 * A blueprint site opens with the theme's demo text in place, and the rewrite
 * takes a while to land. Showing the customer somebody else's copy while they
 * wait, then swapping it under them, makes the moment the page becomes theirs
 * easy to miss. Masking on arrival and revealing when the rewrite lands turns
 * the wait into the point.
 *
 * The mask is a class on the canvas and nothing else. No blocks are touched, so
 * there is nothing to persist, nothing to undo, and nothing that can reach the
 * saved page — which is what makes this safe to run unprompted.
 *
 * @param {boolean} isActive Whether this arrival is a blueprint copy rewrite.
 * @return {boolean} Whether the canvas is currently masked.
 */
export default function useBlueprintCopyMask( isActive ) {
	const { isEditorIframeLoaded, isThinking } = useSelect(
		( select ) => ( {
			isEditorIframeLoaded: select( aiStore ).getIsEditorIframeLoaded(),
			isThinking: select( aiStore ).getIsThinking(),
		} ),
		[]
	);

	const [ isMasked, setIsMasked ] = useState( false );
	const hasStartedRef = useRef( false );
	const wasThinkingRef = useRef( false );

	// Mask as soon as there is a canvas to mask.
	useEffect( () => {
		if ( ! isActive || hasStartedRef.current || ! isEditorIframeLoaded ) {
			return;
		}

		hasStartedRef.current = true;
		setIsMasked( true );
	}, [ isActive, isEditorIframeLoaded ] );

	// Reveal when the agent's turn ends — the rewrite lands as a single edit, so
	// the first completed turn is the page becoming theirs.
	useEffect( () => {
		if ( isThinking ) {
			wasThinkingRef.current = true;
			return;
		}

		if ( wasThinkingRef.current && isMasked ) {
			setIsMasked( false );
		}
	}, [ isThinking, isMasked ] );

	// The backstop. Whatever else happens, the mask comes off.
	useEffect( () => {
		if ( ! isMasked ) {
			return;
		}

		const timer = setTimeout( () => setIsMasked( false ), MASK_TIMEOUT_MS );
		return () => clearTimeout( timer );
	}, [ isMasked ] );

	// Apply it to the canvas the same way the build flow does.
	useEffect( () => {
		if ( ! isEditorIframeLoaded ) {
			return;
		}

		const { canvasiFrame, canvasiFrameRoot } = getCanvasIframeElements();
		if ( ! canvasiFrame ) {
			return;
		}

		// The canvas is whatever the editor hands back, and it is not always a
		// full element — a mask is not worth throwing over.
		canvasiFrame.classList?.toggle( MASK_CLASS, isMasked );
		canvasiFrameRoot?.classList?.toggle( MASK_CLASS, isMasked );

		// Unmounting mid-rewrite must not strand the mask on the canvas.
		return () => {
			canvasiFrame.classList?.remove( MASK_CLASS );
			canvasiFrameRoot?.classList?.remove( MASK_CLASS );
		};
	}, [ isEditorIframeLoaded, isMasked ] );

	return isMasked;
}
