/**
 * WordPress dependencies
 */
import { useDispatch, useRegistry } from '@wordpress/data';
import { useCallback } from '@wordpress/element';
import { store as coreStore } from '@wordpress/core-data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { createBlock, parse, serialize } from '@wordpress/blocks';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import log from '@utils/log-debug.js';

const logNavigationDebug = () => {};

const normalizeNavigationLabel = ( label ) =>
	String( label || '' )
		.trim()
		.toLocaleLowerCase();

/**
 * Hook for handling navigation menu operations.
 *
 * @return {Object} Object containing navigation-related functions.
 */
export default function useNavigation() {
	const registry = useRegistry();
	const { editEntityRecord } = useDispatch( coreStore );

	const getEditorNavigationRefs = useCallback( () => {
		const blockEditor = registry.select( blockEditorStore );
		const getBlocks = blockEditor.getBlocks;
		if ( typeof getBlocks !== 'function' ) {
			return [];
		}
		const refs = new Set();

		const findNavigationRefs = ( blocks = [] ) => {
			blocks.forEach( ( block ) => {
				if (
					block.name === 'core/navigation' &&
					block.attributes?.ref
				) {
					refs.add( block.attributes.ref );
				}

				const innerBlocks =
					getBlocks( block.clientId ) || block.innerBlocks || [];
				if ( innerBlocks.length ) {
					findNavigationRefs( innerBlocks );
				}
			} );
		};

		findNavigationRefs( getBlocks() || [] );
		return [ ...refs ];
	}, [ registry ] );

	const getGlobalNavigation = useCallback( async () => {
		const { navigationId } = registry.select( aiStore ).getSiteMetadata();

		if ( ! navigationId ) {
			return null;
		}

		return await registry
			.resolveSelect( coreStore )
			.getEditedEntityRecord( 'postType', 'wp_navigation', navigationId );
	}, [ registry ] );

	const renameNavigationItem = useCallback(
		async ( navigationId, newTitle, isMatch ) => {
			if ( ! navigationId ) {
				logNavigationDebug( 'rename skipped: missing navigation id', {
					newTitle,
				} );
				return;
			}

			try {
				const navigation = await registry
					.resolveSelect( coreStore )
					.getEditedEntityRecord(
						'postType',
						'wp_navigation',
						navigationId
					);

				if ( ! navigation ) {
					logNavigationDebug(
						'rename skipped: navigation not found',
						{
							navigationId,
							newTitle,
						}
					);
					return;
				}

				const blocks = navigation.blocks ?? parse( navigation.content );
				let matchedBlocks = 0;
				logNavigationDebug( 'rename navigation item start', {
					navigationId,
					newTitle,
					blockCount: blocks?.length || 0,
					blocks: blocks?.map( ( block ) => ( {
						name: block.name,
						id: block.attributes?.id,
						label: block.attributes?.label,
						url: block.attributes?.url,
						type: block.attributes?.type,
						kind: block.attributes?.kind,
					} ) ),
				} );

				const updateBlock = ( block ) => {
					// Check if this block matches
					if ( isMatch( block ) ) {
						matchedBlocks += 1;
						return {
							...block,
							attributes: {
								...block.attributes,
								label: newTitle,
							},
						};
					}

					// If block has innerBlocks, recursively check them
					if ( block.innerBlocks?.length ) {
						return {
							...block,
							innerBlocks: block.innerBlocks.map( updateBlock ),
						};
					}

					return block;
				};

				const updatedBlocks = blocks.map( updateBlock );
				logNavigationDebug( 'rename navigation item result', {
					navigationId,
					newTitle,
					matchedBlocks,
				} );

				if ( matchedBlocks === 0 ) {
					return {
						id: navigationId,
						matchedBlocks,
					};
				}

				const savedRecord = await editEntityRecord(
					'postType',
					'wp_navigation',
					navigationId,
					{
						blocks: updatedBlocks,
						content: serialize( updatedBlocks ),
					},
					{
						throwOnError: true,
					}
				);
				return {
					id: navigationId,
					matchedBlocks,
					savedRecord,
				};
			} catch ( error ) {
				log.error( '[Navigation] Error updating navigation:', error );
				throw error;
			}
		},
		[ editEntityRecord, registry ]
	);

	const renameNavigationItemById = useCallback(
		async ( navigationId, entityId, newTitle, oldTitle ) => {
			if ( ! entityId ) {
				logNavigationDebug( 'rename by id skipped: missing entity id', {
					navigationId,
					newTitle,
					oldTitle,
				} );
				return;
			}

			logNavigationDebug( 'rename by id requested', {
				navigationId,
				entityId,
				newTitle,
				oldTitle,
			} );

			const isMatch = ( block ) => {
				const blockId = block.attributes.id;
				const idMatches = String( blockId ) === String( entityId );
				const labelMatches = oldTitle
					? normalizeNavigationLabel( block.attributes.label ) ===
					  normalizeNavigationLabel( oldTitle )
					: false;

				if ( idMatches || ( ! blockId && labelMatches ) ) {
					// If oldTitle is provided and the block has a page id, only update if
					// the label matches. A match means the user has not changed the label.
					const shouldUpdate =
						! oldTitle || labelMatches || ! blockId;
					logNavigationDebug( 'rename by id candidate', {
						entityId,
						blockId,
						label: block.attributes.label,
						url: block.attributes.url,
						oldTitle,
						idMatches,
						labelMatches,
						matchedByLabelOnly: ! blockId && labelMatches,
						shouldUpdate,
					} );
					return shouldUpdate;
				}
				return false;
			};

			return renameNavigationItem( navigationId, newTitle, isMatch );
		},
		[ renameNavigationItem ]
	);

	const renameNavigationItemByLabel = useCallback(
		async ( navigationId, oldTitle, newTitle ) => {
			if ( ! oldTitle ) {
				return;
			}

			return renameNavigationItem(
				navigationId,
				newTitle,
				( block ) => block.attributes.label === oldTitle
			);
		},
		[ renameNavigationItem ]
	);

	const renameGlobalNavigationById = useCallback(
		async ( entityId, newTitle, oldTitle ) => {
			const editorNavigationRefs = getEditorNavigationRefs();
			logNavigationDebug( 'editor navigation refs resolved', {
				editorNavigationRefs,
				entityId,
				newTitle,
				oldTitle,
			} );

			for ( const navigationRef of editorNavigationRefs ) {
				const result = await renameNavigationItemById(
					navigationRef,
					entityId,
					newTitle,
					oldTitle
				);
				if ( result?.matchedBlocks > 0 ) {
					return result;
				}
			}

			if ( editorNavigationRefs.length ) {
				return {
					id: editorNavigationRefs[ 0 ],
					matchedBlocks: 0,
				};
			}

			const navigation = await getGlobalNavigation();
			if ( ! navigation?.id ) {
				logNavigationDebug( 'global navigation missing', {
					entityId,
					newTitle,
					oldTitle,
				} );
				return;
			}

			logNavigationDebug(
				'no editor navigation refs found; falling back to metadata navigation',
				{
					navigationId: navigation.id,
					entityId,
					newTitle,
					oldTitle,
				}
			);

			return renameNavigationItemById(
				navigation.id,
				entityId,
				newTitle,
				oldTitle
			);
		},
		[
			getEditorNavigationRefs,
			getGlobalNavigation,
			renameNavigationItemById,
		]
	);

	const addNavigationItems = useCallback(
		async ( itemsData, navigationMenu ) => {
			if (
				! itemsData ||
				! Array.isArray( itemsData ) ||
				itemsData.length === 0
			) {
				return;
			}

			if ( ! navigationMenu ) {
				navigationMenu = await getGlobalNavigation();
				if ( ! navigationMenu?.id ) {
					return;
				}
			}

			const navBlocks =
				navigationMenu.blocks ?? parse( navigationMenu.content );

			const newNavigationBlocks = itemsData.map( ( itemData ) =>
				createBlock( 'core/navigation-link', {
					label: itemData.label,
					type: itemData.type || 'page',
					id: itemData.id,
					url: itemData.url,
					kind: itemData.kind || 'post-type',
				} )
			);

			await editEntityRecord(
				'postType',
				'wp_navigation',
				navigationMenu.id,
				{
					blocks: [ ...navBlocks, ...newNavigationBlocks ],
					content: ( entity ) => serialize( entity.blocks ?? [] ),
				}
			);
		},
		[ editEntityRecord, getGlobalNavigation ]
	);

	return {
		getGlobalNavigation,
		renameNavigationItemById,
		renameNavigationItemByLabel,
		renameGlobalNavigationById,
		addNavigationItems,
	};
}
