/**
 * WordPress dependencies
 */
import { useDispatch } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import { blankBuildTemplateParts, insertDummySections } from '@utils/canvas';
import useCanvas from '@hooks/use-canvas';
import usePages from '@hooks/use-pages';
import useSaveEverything from '@hooks/use-save-everything';
import bumpMcStat from '@utils/bump-mc-stat';
import log from '@utils/log-debug.js';
import useTemplates from '@hooks/use-templates';

// Number of flashing placeholder sections created for the "Planning your site"
// step, before get_site_structure returns the real count. Because we call
// insertDummySections() with replaceTemplateParts: false, one placeholder is
// consumed for the header slot, so the body renders one fewer than this count.
// Sized to fill the viewport so the canvas doesn't read as blank while the
// real structure is still being planned.
const DEFAULT_SKELETON_SECTION_COUNT = 8;

export default function useBuildSite() {
	const saveEverything = useSaveEverything();
	const { zoomIn } = useCanvas();

	const { setShowWelcomeGuide } =
		useDispatch( 'automattic/wpcom-welcome-guide' ) ?? {}; // eslint-disable-line @wordpress/data-no-store-string-literals

	const {
		setIsBuildingSite,
		setIsSiteBuildStructurePhase,
		setThinkingMessage,
		runSiteBuildAgent,
		setBuildErrorDialog,
	} = useDispatch( aiStore );
	const { __unstableSetEditorMode } = useDispatch( blockEditorStore );
	const { renamePage, homePageId, deleteAllBigSkyPagesExceptHome } =
		usePages();
	const { changeHomePageTemplate } = useTemplates();

	const buildSite = async () => {
		// Add onboarded class to body to hide Big Sky logo
		document.body.classList.add( 'big-sky-onboarded' );

		setIsBuildingSite( true );
		setIsSiteBuildStructurePhase( true );
		setThinkingMessage( __( 'Planning your site', 'big-sky' ) );

		// Open the unified chat right away so the "Planning your site" checklist
		// appears the instant the build starts, instead of only once
		// runSiteBuildAgent opens it after the skeleton prep below. The building
		// state and thinking message are set above first, so the chat picks them
		// up as it mounts (see useSyncBuildStateOnMount). Dock it so the build
		// progress sits in the sidebar rather than a floating window. Both are
		// no-ops when there is no unified chat — non-unified flows use the Big
		// Sky dock instead.
		window.__agentsManagerActions?.setChatOpen( true );
		window.__agentsManagerActions?.setChatDocked( true );

		// The skeleton prep (blank template parts + insert placeholders) is inside
		// the try so a failure there (e.g. the editor store not being ready) is
		// handled the same as a build failure: the error dialog shows and the
		// finally resets the building/structure flags, instead of leaving the UI
		// stuck with no visible progress and no way to recover.
		let restoreBlankedTemplateParts;
		try {
			// clean up existing pages that were generated by Big Sky
			await deleteAllBigSkyPagesExceptHome();
			await changeHomePageTemplate();
			// Blank the saved header/footer template parts so the canvas shows a
			// clean page during the "Planning your site" step instead of the
			// previous site's content. Compose replaces these with real patterns.
			// The returned callback restores them if the build fails, so the
			// blanked (dirty) entities can't be saved over the real ones.
			restoreBlankedTemplateParts = await blankBuildTemplateParts();
			// Fill the body with flashing placeholder sections so the user sees a
			// skeleton during the structure phase (replaceTemplateParts: false —
			// the header/footer are handled by the entity blank above).
			await insertDummySections( {
				count: DEFAULT_SKELETON_SECTION_COUNT,
				replaceTemplateParts: false,
			} );
			bumpMcStat( 'big-sky-onboarding', 'build-start' );

			// Don't try to rename the home page if it doesn't exist.
			if ( homePageId ) {
				await renamePage( homePageId, 'Home', undefined, {
					save: true,
				} );
			}
			// make sure welcome guide is hidden
			if ( setShowWelcomeGuide ) {
				setShowWelcomeGuide( false );
			}

			// Call workflow agent to handle the entire site build process
			await runSiteBuildAgent( 'buildSite' );

			// finished successfully
			bumpMcStat( 'big-sky-onboarding', 'build-complete' );
			saveEverything();
			__unstableSetEditorMode( 'edit' );
			zoomIn();
		} catch ( error ) {
			log.error( '❌ Site build failed:', error );
			// Put the real header/footer back so the abandoned blank edits can't
			// be persisted over them by a later save.
			await restoreBlankedTemplateParts?.();
			// Remove onboarded class to body to show Big Sky logo
			document.body.classList.remove( 'big-sky-onboarded' );
			// Show error dialog - user will be returned to site spec after acknowledging
			setBuildErrorDialog( {
				isOpen: true,
				message:
					error?.message || __( 'Something went wrong.', 'big-sky' ),
			} );
		} finally {
			setIsBuildingSite( false );
			setIsSiteBuildStructurePhase( false );
		}
	};

	return {
		buildSite,
	};
}
