/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from '@wordpress/data';
import { store as coreStore } from '@wordpress/core-data';
import { store as editorStore } from '@wordpress/editor';
import { __ } from '@wordpress/i18n';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import useStyles from '@hooks/use-styles';
import useTemplates from '@hooks/use-templates';
import useSiteMetadata from '@hooks/use-site-metadata';
import { defaultSiteMetadata } from '@utils/constants';
import usePages from '@hooks/use-pages';
import useCanvas from '@hooks/use-canvas';
import { useRouting } from '@hooks/use-routing';

export default function useResetSite() {
	const { getCurrentPostId } = useSelect( editorStore );
	const { getEntityRecord } = useSelect( coreStore );
	const { savePost } = useDispatch( editorStore );
	const { saveEntityRecord } = useDispatch( coreStore );
	const { resetStyles } = useStyles();
	const { changeHomePageTemplate, resetTemplates } = useTemplates();
	const { setSiteMetadata } = useSiteMetadata();
	const { deleteAllBigSkyPagesExceptHome, goToHomePage } = usePages();
	const { clearBlocks } = useCanvas();
	const { setAiStep } = useRouting();
	const {
		clearMessages,
		assistantSay,
		resetCachedContent,
		setHeaderSectionIsReady,
		setInputtedFiles,
		clearGeneratedVariations,
		setCurrentColor,
		setCurrentFont,
		setThinking,
	} = useDispatch( aiStore );

	const resetSite = async () => {
		const currentPostId = getCurrentPostId();
		const homePageId = getEntityRecord( 'root', 'site' )?.page_on_front;
		deleteAllBigSkyPagesExceptHome();
		resetStyles();
		resetTemplates();
		setSiteMetadata( { ...defaultSiteMetadata }, true );
		setInputtedFiles( [] );
		resetCachedContent();
		setCurrentColor( null );
		setCurrentFont( null );
		clearGeneratedVariations();
		setHeaderSectionIsReady( false );
		clearMessages();
		if ( homePageId !== currentPostId ) {
			await savePost(); //save the current post to prevent user getting a second confirmation.
			// If not on the front page, clear the content of the front page.
			saveEntityRecord( 'postType', 'page', {
				id: homePageId,
				content: '',
			} );

			await goToHomePage();
			return;
		}
		// change home page template to default template
		await changeHomePageTemplate( true );
		setAiStep( 'spec', true );
		await clearBlocks(); //saveEntityRecord doen't seem to work if on the current page so clear the blocks instead.
		await savePost();
	};

	const buildNewSite = (
		message = __(
			'You can rebuild your site from here. Either build a new site with the same details, or modify them and then rebuild.',
			'big-sky'
		)
	) => {
		clearMessages();
		setHeaderSectionIsReady( false );
		setAiStep( 'spec', true );
		setThinking( false );
		assistantSay( message );
	};

	return {
		resetSite,
		buildNewSite,
	};
}
