/**
 * WordPress dependencies
 */
import { store as blockEditorStore } from '@wordpress/block-editor';
import { useDispatch, useSelect } from '@wordpress/data';
import { useCallback } from '@wordpress/element';

/**
 * Internal dependencies
 */
import { unlock } from '@utils/lock-unlock.js';
import { TemplatePartSlug } from '@utils/template-parts';
import { PROCESSING_FEATURES } from '@utils/constants';
import {
	getAllProcessingFeatures,
	isValidProcessingFeature,
} from '@utils/processing-features';
import { getBlockElement } from '@utils/block-dom';
import { resetAllBlockProcessingStates } from '@utils/block-processing-state';

export default function useBlocks() {
	const {
		getBlockHierarchyRootClientId,
		getBlock,
		getBlocksByName,
		getClientIdsOfDescendants,
		getBlocks,
		getSectionRootClientId,
	} = useSelect( ( select ) => {
		const store = select( blockEditorStore );
		const { getSectionRootClientId: _getSectionRootClientId } =
			unlock( store );
		return {
			getBlockHierarchyRootClientId: store.getBlockHierarchyRootClientId,
			getBlock: store.getBlock,
			getBlocksByName: store.getBlocksByName,
			getClientIdsOfDescendants: store.getClientIdsOfDescendants,
			getBlockParentsByBlockName: store.getBlockParentsByBlockName,
			getBlocks: store.getBlocks,
			getSectionRootClientId: _getSectionRootClientId,
		};
	}, [] );
	const { updateBlockAttributes } = useDispatch( blockEditorStore );

	const getSurroundingContentOfBlock = useCallback(
		( block ) => {
			const rootParentBlockClientID = getBlockHierarchyRootClientId(
				block?.clientId
			);
			const rootParentBlock = getBlock( rootParentBlockClientID );
			const allChildBlocksClientIDs = getClientIdsOfDescendants(
				rootParentBlock?.clientId
			);

			let surroundingContent = '';
			allChildBlocksClientIDs.forEach( ( clientID ) => {
				const childBlock = getBlock( clientID );
				if (
					childBlock.name === 'core/heading' ||
					childBlock.name === 'core/paragraph'
				) {
					surroundingContent += ' ' + childBlock.attributes.content;
				}
			} );

			return surroundingContent;
		},
		[ getBlockHierarchyRootClientId, getBlock, getClientIdsOfDescendants ]
	);

	const setBlockIsProcessing = useCallback(
		( block, isProcessing ) => {
			// Determine processing features based on block name
			const getProcessingFeaturesForBlock = ( blockName ) => {
				// Map block names to processing features
				const blockFeatureMap = {
					'core/heading': [ PROCESSING_FEATURES.CONTENT ],
					'core/paragraph': [ PROCESSING_FEATURES.CONTENT ],
					'core/button': [ PROCESSING_FEATURES.CONTENT ],
					'core/site-title': [ PROCESSING_FEATURES.CONTENT ],
					'core/image': [ PROCESSING_FEATURES.IMAGES ],
					'core/cover': [ PROCESSING_FEATURES.BACKGROUND_IMAGES ],
					'core/group': [ PROCESSING_FEATURES.ALL ],
					'core/columns': [ PROCESSING_FEATURES.ALL ],
					'core/column': [ PROCESSING_FEATURES.ALL ],
					'core/template-part': [ PROCESSING_FEATURES.ALL ],
					'core/block': [ PROCESSING_FEATURES.ALL ],
				};

				// Return specific features for known blocks, or ALL for unknown blocks
				return (
					blockFeatureMap[ blockName ] || [ PROCESSING_FEATURES.ALL ]
				);
			};

			const features = getProcessingFeaturesForBlock( block?.name );

			// Validate features
			const invalidFeatures = features.filter(
				( feature ) => ! isValidProcessingFeature( feature )
			);
			if ( invalidFeatures.length > 0 ) {
				throw new Error(
					`Invalid processing features: ${ invalidFeatures.join(
						', '
					) }. Allowed features are: ${ getAllProcessingFeatures().join(
						', '
					) }`
				);
			}

			const blockElement = getBlockElement( block );
			if ( ! blockElement ) {
				return;
			}

			Array.from( blockElement.classList ).forEach( ( className ) => {
				if (
					className.startsWith( 'big-sky__is-processing' ) ||
					className.startsWith( 'big-sky__has-processed' )
				) {
					blockElement.classList.remove( className );
				}
			} );

			if ( isProcessing ) {
				// Set processing state
				blockElement.dataset.bigSkyProcessingState = 'processing';
				blockElement.dataset.bigSkyProcessingFeatures =
					features.join( ',' );

				const processingClasses = features.includes(
					PROCESSING_FEATURES.ALL
				)
					? [ 'big-sky__is-processing' ]
					: features.map(
							( feature ) => `big-sky__is-processing-${ feature }`
					  );

				// Add processing classes based on features
				processingClasses.forEach( ( className ) => {
					blockElement.classList.add( className );
				} );

				// Try to update className for all blocks (most blocks support it)
				const existingClasses =
					block.attributes?.className
						?.split( ' ' )
						.filter( Boolean ) || [];

				// Remove any existing big-sky classes and add the new ones
				const filteredClasses = existingClasses.filter(
					( className ) => ! className.startsWith( 'big-sky__' )
				);
				const newClasses = [ ...filteredClasses, ...processingClasses ];

				// update the block attributes directly as well, in case it's in memory
				if ( block.attributes ) {
					block.attributes.className = newClasses.join( ' ' );
				}
				updateBlockAttributes( block.clientId, {
					className: newClasses.join( ' ' ),
				} );
			} else {
				// Clear processing state
				delete blockElement.dataset.bigSkyProcessingState;
				delete blockElement.dataset.bigSkyProcessingFeatures;
				blockElement.classList.add( 'big-sky__has-processed' );

				// Remove processing classes from the block attributes
				if ( block.attributes ) {
					block.attributes.className = block.attributes?.className
						?.split( ' ' )
						.filter(
							( className ) =>
								! className.startsWith( 'big-sky__' )
						)
						.join( ' ' );
				}
				updateBlockAttributes( block.clientId, {
					className: block.attributes?.className
						?.split( ' ' )
						.filter(
							( className ) =>
								! className.startsWith( 'big-sky__' )
						)
						.join( ' ' ),
				} );
			}
		},
		[ updateBlockAttributes ]
	);

	const getTemplatePartClientID = useCallback(
		( name ) => {
			const templatePartClientIds =
				getBlocksByName( 'core/template-part' );

			if ( ! templatePartClientIds ) {
				return;
			}

			return templatePartClientIds.find( ( clientId ) => {
				const block = getBlock( clientId );
				return block.attributes.slug === name;
			} );
		},
		[ getBlocksByName, getBlock ]
	);

	const getRootBlocks = useCallback(
		( includeParents = false ) => {
			const sectionRootClientId = getSectionRootClientId();
			const rootContentBlocks = getBlocks( sectionRootClientId );

			const headerClientId = getTemplatePartClientID(
				TemplatePartSlug.Header
			);
			const headerHeroClientId = getTemplatePartClientID(
				TemplatePartSlug.HeaderHero
			);
			const footerClientId = getTemplatePartClientID(
				TemplatePartSlug.Footer
			);

			const header = getBlocks( headerClientId );
			const headerHero = getBlocks( headerHeroClientId );
			const footer = getBlocks( footerClientId );

			const baseBlocks = [
				...rootContentBlocks,
				...headerHero,
				...header,
				...footer,
			];

			if ( ! includeParents ) {
				return baseBlocks;
			}

			// Get the block objects themselves if includeParents is true.
			// This is mainly used to ensure processing states are removed from all blocks.
			const sectionRootBlock = getBlock( sectionRootClientId );
			const headerBlock = getBlock( headerClientId );
			const headerHeroBlock = getBlock( headerHeroClientId );
			const footerBlock = getBlock( footerClientId );

			return [
				...baseBlocks,
				sectionRootBlock,
				headerBlock,
				headerHeroBlock,
				footerBlock,
			].filter( Boolean );
		},
		[ getSectionRootClientId, getBlocks, getTemplatePartClientID, getBlock ]
	);

	const resetAllBlockIsProcessing = useCallback( () => {
		// Use the shared utility function for consistent cleanup
		// This ensures both DOM and block attributes are properly cleaned
		resetAllBlockProcessingStates();
	}, [] );

	return {
		getRootBlocks,
		getSurroundingContentOfBlock,
		getSectionRootClientId,
		getTemplatePartClientID,
		setBlockIsProcessing,
		resetAllBlockIsProcessing,
	};
}
