/**
 * External dependencies
 */
import { nanoid } from 'nanoid';

/**
 * WordPress dependencies
 */
import { select } from '@wordpress/data';
import { store as blockEditorStore } from '@wordpress/block-editor';
import { store as blocksStore, parse } from '@wordpress/blocks';
import { store as editorStore } from '@wordpress/editor';
import { store as coreStore } from '@wordpress/core-data';
import log from '@utils/log-debug.js';

/**
 * Internal dependencies
 */
import { getCurrentScreenContext } from '@utils/env.js';
import { unlock } from '@utils/lock-unlock.js';
import { TemplatePartSlug, templatePartSlugs } from '@utils/template-parts.js';
import { getStyleValue } from '@utils/global-styles.js';
import { serializePostContentBody } from '@shared/serialize-post-content';
import { getSelectedTextContext } from './text-selection.ts';

/**
 * Get edited entity records.
 * This will retrieve the edits made to the entity records.
 * We need to do this because the edits are not yet saved to the backend so we need to send the "work in progress".
 *
 * @return {Object} Edited entity records
 */
function getEditedEntityRecords() {
	const { __experimentalGetDirtyEntityRecords, getEntityRecordEdits } =
		select( coreStore );
	const editedEntityRecords = {};
	__experimentalGetDirtyEntityRecords().forEach( ( record ) => {
		const edits = getEntityRecordEdits(
			record.kind,
			record.name,
			record.key
		);
		editedEntityRecords[
			`${ record.kind?.toString() || '' }/${
				record.name?.toString() || ''
			}/${ record.key?.toString() || '' }`
		] = JSON.parse( JSON.stringify( edits ) );
	} );
	return editedEntityRecords;
}

/**
 * Compress client IDs for context - extracted from use-agentic-context.js
 *
 * @param {Object}   root0             - Parameters object
 * @param {Array}    root0.blocks      - Array of blocks to compress
 * @param {Object}   root0.clientIdMap - Map of client IDs to compress
 * @param {Function} root0.dispatch    - Dispatch function
 * @return {Array} Compressed blocks array
 */
const compressClientIds = ( { blocks, clientIdMap, dispatch } ) => {
	const navigationItemMap = {};
	const compressBlock = ( block, navigationRef = null ) => {
		if ( ! block?.clientId ) return block;

		// Find if we already have a shortId for this clientId
		const shortId = Object.keys( clientIdMap ).find(
			( key ) => clientIdMap[ key ] === block.clientId
		);

		// If we don't have a shortId yet, generate one
		const id = shortId || nanoid( 4 );

		// Store the mapping if it's a new id
		if ( ! shortId ) {
			clientIdMap[ id ] = block.clientId;
		}

		const nextNavigationRef =
			block.name === 'core/navigation'
				? block.attributes?.ref
				: navigationRef;

		if (
			nextNavigationRef &&
			( block.name === 'core/navigation-link' ||
				block.name === 'core/navigation-submenu' )
		) {
			navigationItemMap[ id ] = {
				ref: nextNavigationRef,
				attributes: block.attributes || {},
			};
		}

		// Create the compressed block with the short id
		const compressed = {
			...block,
			clientId: id,
		};

		// Recursively compress innerBlocks if they exist
		if ( block.innerBlocks ) {
			compressed.innerBlocks = block.innerBlocks.map( ( b ) =>
				compressBlock( b, nextNavigationRef )
			);
		}

		return compressed;
	};

	// Process each block in the array
	const compressedBlocks = blocks.map( ( block ) => compressBlock( block ) );

	// Update state with the final clientIdMap after all blocks are processed
	dispatch.setFullPageStructure( {
		clientIdMap,
		navigationItemMap,
	} );

	return compressedBlocks;
};

/**
 * Get section root client ID using the same logic as useBlocks hook
 *
 * @return {string|null} Section root client ID or null
 */
const getSectionRootClientId = () => {
	try {
		// Use the same unlock pattern as useBlocks hook
		const { getSectionRootClientId: _getSectionRootClientId } = unlock(
			select( blockEditorStore )
		);
		return _getSectionRootClientId();
	} catch ( error ) {
		console.error( 'Error getting section root client ID:', error );
		return null;
	}
};

const getNavigationEntityBlocks = ( ref ) => {
	if ( ! ref ) {
		return null;
	}

	const coreSelect = select( coreStore );
	const navigationEntity =
		coreSelect.getEditedEntityRecord?.(
			'postType',
			'wp_navigation',
			ref
		) || coreSelect.getEntityRecord?.( 'postType', 'wp_navigation', ref );

	if ( ! navigationEntity ) {
		return null;
	}

	if (
		Array.isArray( navigationEntity.blocks ) &&
		navigationEntity.blocks.length
	) {
		return navigationEntity.blocks;
	}

	const content =
		typeof navigationEntity.content === 'string'
			? navigationEntity.content
			: navigationEntity.content?.raw ||
			  navigationEntity.content?.rendered;

	if ( ! content ) {
		return null;
	}

	try {
		return parse( content );
	} catch ( error ) {
		console.warn( 'Error parsing navigation block content:', error );
		return null;
	}
};

export function getCurrentPageContent( dispatch, clientIdMap ) {
	const { getBlocks, getBlocksByName, getBlock, getBlockParents } =
		select( blockEditorStore );
	// Get both template blocks and post content blocks using the same logic as original
	const sectionRootClientId = getSectionRootClientId();
	// If section root exists, get blocks from there; otherwise get all root-level blocks
	const sectionRootBlocks = sectionRootClientId
		? getBlocks( sectionRootClientId )
		: getBlocks(); // Fallback to all root-level blocks when no section root

	// Get header and footer template parts
	const templatePartBlocks = getBlocksByName( 'core/template-part' );
	let headerBlock = templatePartBlocks?.find(
		( block ) =>
			getBlock( block )?.attributes?.slug === TemplatePartSlug.HeaderHero
	);
	if ( ! headerBlock ) {
		headerBlock = templatePartBlocks?.find(
			( block ) =>
				getBlock( block )?.attributes?.slug === TemplatePartSlug.Header
		);
	}
	const rawFooterBlock = templatePartBlocks?.find(
		( block ) =>
			getBlock( block )?.attributes?.slug === TemplatePartSlug.Footer
	);

	const contentBlocks = sectionRootBlocks.filter(
		( b ) =>
			b.name !== 'core/template-part' ||
			! templatePartSlugs.includes( b.attributes?.slug )
	);
	// A theme can wrap a template part in a block that carries content of its own:
	// a cover around the header, say, holding the headline, subhead and call to
	// action as the cover's own children. That wrapper sits outside the section
	// root and matches no template-part slug, so collecting the bare part left
	// everything the wrapper holds in no region at all — the agent would rewrite
	// each section it could see and leave that copy standing.
	//
	// Report the wrapper as the region instead. Nothing is duplicated — the part is
	// still in there, one level down — and a region the agent can see is a region
	// it can fix.
	const sectionRootAncestors = sectionRootClientId
		? getBlockParents( sectionRootClientId ) ?? []
		: [];

	/**
	 * Widen a template part to the wrapper that carries its section's content.
	 *
	 * Walks outward to the outermost ancestor that does not also contain the
	 * content region. Stopping there matters: themes that wrap the whole template
	 * in a single root group would otherwise report that group as the header,
	 * swallowing the page content and the footer along with it and reporting them
	 * twice over.
	 *
	 * @param {string} block Client ID of the template part, if it was found.
	 * @return {string} The wrapper to report, or the part itself when it is bare.
	 */
	const widenToWrapper = ( block ) => {
		if ( ! block ) {
			return block;
		}

		const ancestors = getBlockParents( block ) ?? [];

		// Nested inside the content region, so it is already accounted for there.
		if ( ancestors.includes( sectionRootClientId ) ) {
			return block;
		}

		// Ancestors run outermost first, so the first one that clears the content
		// region is the widest wrapper that still belongs to this section alone.
		const wrapper = ancestors.find(
			( ancestor ) =>
				ancestor !== sectionRootClientId &&
				! sectionRootAncestors.includes( ancestor )
		);

		return wrapper ?? block;
	};

	headerBlock = widenToWrapper( headerBlock );
	let footerBlock = widenToWrapper( rawFooterBlock );

	// A wrapper shared by both regions belongs to neither; reporting it twice would
	// duplicate everything inside it.
	if ( footerBlock && footerBlock === headerBlock ) {
		footerBlock = rawFooterBlock;
	}

	// Get inner blocks of header and footer
	// For template parts, we need to explicitly fetch their inner blocks
	const headerBlocks = headerBlock ? getBlocks( headerBlock ) : [];
	const footerBlocks = footerBlock ? getBlocks( footerBlock ) : [];

	// Process template parts recursively to ensure they have their inner blocks.
	// Navigation blocks store their links in a referenced wp_navigation entity, so
	// include those entity blocks in the page structure too.
	const processTemplatePartBlocks = ( blocks ) => {
		return blocks.map( ( block ) => {
			const processedBlock = { ...block };

			if ( block.name === 'core/template-part' ) {
				processedBlock.innerBlocks = getBlocks( block.clientId );
			}

			if ( block.name === 'core/navigation' ) {
				const navigationBlocks = getNavigationEntityBlocks(
					block.attributes?.ref
				);

				if ( navigationBlocks ) {
					processedBlock.innerBlocks = navigationBlocks;
				}
			}

			// Recursively process inner blocks
			if ( processedBlock.innerBlocks?.length > 0 ) {
				processedBlock.innerBlocks = processTemplatePartBlocks(
					processedBlock.innerBlocks
				);
			}

			return processedBlock;
		} );
	};

	// Apply template part processing to all block collections
	const processedHeaderBlocks = processTemplatePartBlocks( headerBlocks );
	const processedFooterBlocks = processTemplatePartBlocks( footerBlocks );
	const processedContentBlocks = processTemplatePartBlocks( contentBlocks );

	// Process all blocks and join their HTML
	const allBlocks = [];

	// Add header blocks if they exist
	if ( processedHeaderBlocks.length ) {
		allBlocks.push( {
			// Not always a template part now that a wrapper can stand in for it.
			name: getBlock( headerBlock )?.name ?? 'core/template-part',
			type: 'header',
			clientId: headerBlock,
			attributes: { ...getBlock( headerBlock )?.attributes },
			innerBlocks: processedHeaderBlocks,
		} );
	}

	// Add content blocks
	// If section root exists, wrap content blocks in the section root container
	// Otherwise, add content blocks directly (for pages without a main wrapper)
	if ( sectionRootClientId ) {
		allBlocks.push( {
			name: getBlock( sectionRootClientId )?.name,
			type: 'content',
			clientId: sectionRootClientId,
			innerBlocks: processedContentBlocks ?? [],
		} );
	} else if ( processedContentBlocks.length ) {
		// No section root, add content blocks directly
		allBlocks.push( ...processedContentBlocks );
	}

	// Add footer blocks if they exist
	if ( processedFooterBlocks.length ) {
		allBlocks.push( {
			// Not always a template part now that a wrapper can stand in for it.
			name: getBlock( footerBlock )?.name ?? 'core/template-part',
			type: 'footer',
			clientId: footerBlock,
			attributes: { ...getBlock( footerBlock )?.attributes },
			innerBlocks: processedFooterBlocks,
		} );
	}

	const compressedBlocks = compressClientIds( {
		blocks: allBlocks,
		clientIdMap,
		dispatch,
	} );

	return compressedBlocks;
}

/**
 * Get unique block schemas for blocks used on the current page
 *
 * @param {Array} pageContent - The page content blocks from getCurrentPageContent
 * @return {Array} Array of unique block type objects for blocks used on the page
 */
function getBlockSchemasFromPageContent( pageContent ) {
	const { getBlockType } = select( blocksStore );
	const blockTypes = new Set();

	// Recursively collect all block types used on the page
	const collectBlockTypes = ( blocks ) => {
		if ( ! Array.isArray( blocks ) ) {
			return;
		}

		blocks.forEach( ( block ) => {
			if ( block.name ) {
				blockTypes.add( block.name );
			}
			if ( block.innerBlocks ) {
				collectBlockTypes( block.innerBlocks );
			}
		} );
	};

	// Collect block types from page content
	collectBlockTypes( pageContent );

	// Get schemas for each unique block type and return as array
	return Array.from( blockTypes )
		.filter(
			( blockName ) =>
				! blockName.startsWith( 'core/' ) &&
				! blockName.startsWith( 'jetpack/' )
		)
		.map( ( blockName ) => {
			const blockType = getBlockType( blockName );
			if ( ! blockType ) {
				return null;
			}

			const additionalInstructions =
				getBlockAdditionalInstructions( blockName );

			// Return only important schema details
			const filteredSchema = {
				attributes: blockType.attributes,
				category: blockType.category,
				description: blockType.description,
				keywords: blockType.keywords,
				name: blockType.name,
				supports: blockType.supports,
				title: blockType.title,
				providesContext: blockType.providesContext,
			};

			// Add additional_instructions if they exist
			if ( additionalInstructions ) {
				filteredSchema.additional_instructions = additionalInstructions;
			}

			return filteredSchema;
		} )
		.filter( ( blockType ) => blockType );
}

/**
 * Get additional AI-specific instructions for block types
 *
 * @param {string} blockName - The block name to get instructions for
 * @return {string|null} Additional instructions or null if none
 */
function getBlockAdditionalInstructions( blockName ) {
	const blockInstructions = {
		// WooCommerce blocks
		'woocommerce/product-collection':
			'Treat the collection as a grid of columns and rows. The total of the columns * rows should equal the number of products to display. For example, if columns is 3 and rows is 2, display 6 products in total. Any reference to cats means the number of columns.',

		// Add more block-specific instructions as needed
	};

	return blockInstructions[ blockName ] || null;
}

/**
 * Create a context provider function from store selectors
 * This extracts the logic from useAgenticContext without React hooks
 *
 * @param {Function} dispatch         - AI store dispatch function
 * @param {Object}   clientIdMap      - Client ID mapping from store
 * @param {Function} getInputtedFiles - Function to get uploaded file URLs
 * @return {Object} ContextProvider object with getClientContext method
 */

export function createContextProviderFromStore(
	dispatch,
	clientIdMap,
	getInputtedFiles
) {
	// Create the context callback function
	const getClientContextCallback = () => {
		const blocks = select( blocksStore ).getBlockTypes();

		const availableBlocks = blocks.map( ( block ) => ( {
			name: block.name,
			description: block.description,
		} ) );

		// Get block editor selectors using WordPress data select
		const { getSelectedBlockClientId } = select( blockEditorStore );

		// Get current page content - extracted from useAgenticContext logic

		const getSelectBlockShortId = ( clientId ) => {
			return Object.keys( clientIdMap ).find(
				( key ) => clientIdMap[ key ] === clientId
			);
		};

		const currentPageId = select( editorStore ).getCurrentPostId();

		const getTemplateFromCurrentPostId = ( currentPostId ) => {
			// if not is string currentPostId, return null
			if ( typeof currentPostId !== 'string' ) {
				return null;
			}
			const slugIndex = currentPostId?.indexOf( '//' );
			if ( ! slugIndex || slugIndex < 0 ) {
				return null;
			}
			return currentPostId.substring( slugIndex + 2 );
		};

		const getCurrentPageTemplateSlug = () => {
			// First, check if we're editing a template directly (post ID contains '//')
			const templateFromPostId =
				getTemplateFromCurrentPostId( currentPageId );
			if ( templateFromPostId ) {
				return templateFromPostId;
			}
			// Otherwise, get the template assigned to the current page/post
			const { getEditedPostAttribute } = select( editorStore );
			return getEditedPostAttribute( 'template' ) || null;
		};

		const uploadedFileIds = getInputtedFiles().map( ( file ) => file.id );
		// Inline text selection inside the selected block, if any.
		const selectedTextContext = getSelectedTextContext();
		const currentPageContent = getCurrentPageContent(
			dispatch,
			clientIdMap
		);
		const currentPageContentMarkup = serializePostContentBody(
			select( blockEditorStore ).getBlocks
		);

		// Get current custom CSS from global styles.
		const {
			__experimentalGetCurrentGlobalStylesId: getGlobalStylesId,
			getEditedEntityRecord,
		} = select( coreStore );
		const globalStylesId = getGlobalStylesId?.();
		let customCSS = '';
		if ( globalStylesId ) {
			const globalStyles = getEditedEntityRecord(
				'root',
				'globalStyles',
				globalStylesId
			);
			customCSS = getStyleValue( globalStyles, 'css', null, false ) || '';
		}

		return {
			availableBlocks,
			editedEntityRecords: getEditedEntityRecords(),
			current_page_id: currentPageId,
			currentTemplateId: getTemplateFromCurrentPostId( currentPageId ),
			currentPageUsesHeroTemplate:
				getCurrentPageTemplateSlug() === 'template-page-w-hero',
			currentPageContent,
			...( currentPageContentMarkup ? { currentPageContentMarkup } : {} ),
			selectedBlockClientId:
				getSelectBlockShortId( getSelectedBlockClientId() ) || '',
			...( selectedTextContext
				? { selectedText: selectedTextContext }
				: {} ),
			uploadedFiles: uploadedFileIds,
			blockSchema: getBlockSchemasFromPageContent( currentPageContent ),
			environment: 'wp-admin',
			url: window.location.href,
			customCSS,
			currentScreen: getCurrentScreenContext(),
			selectedSiteId:
				window?.JP_CONNECTION_INITIAL_STATE?.userConnectionData
					?.currentUser?.blogId || '',
		};
	};

	// Return the ContextProvider object (matching useClientContext interface)
	return {
		getClientContext: () => {
			try {
				// Call the context callback to get fresh context data
				const context = getClientContextCallback() || {};

				return {
					...context,
					constructorArguments: {
						...( context.constructorArguments || {} ),
						// Pass client surface into backend constructor args.
						client: 'site-editor',
					},
				};
			} catch ( error ) {
				// Log error but don't break the message sending
				console.error( 'Error getting client context:', error );
				return {};
			}
		},
	};
}

/**
 * Create a tool provider that uses the WordPress Abilities API
 * The agenttic-client library has native support for the Abilities API via getAbilities callback
 *
 * @return {Object} ToolProvider object with getAbilities function
 */
export function createToolProviderFromStore() {
	const { getAbilities } = window?.wp?.abilities || {};

	if ( ! getAbilities ) {
		log.error(
			'WordPress Abilities API not available. Make sure wp-abilities script is enqueued.'
		);
	}

	// Return a tool provider with getAbilities callback
	// The agenttic-client will handle converting abilities to tools and executing them
	const wrappedGetAbilities = async () => {
		if ( ! getAbilities ) {
			log.warning( 'getAbilities not available, returning empty array' );
			return [];
		}

		try {
			// Get abilities from the WordPress Abilities API
			// Filter to only include big-sky category abilities
			const abilities = await getAbilities( { category: 'big-sky' } );

			// Filter to only client-side abilities (those with a callback function)
			// Server-side abilities don't have a callback property
			const clientAbilities = abilities.filter(
				( ability ) => typeof ability.callback === 'function'
			);

			// Ensure category is set on all abilities (WordPress Abilities API might strip it)
			const abilitiesWithCategory = clientAbilities.map(
				( ability ) => ( {
					...ability,
					category: ability.category || 'big-sky', // Ensure category is always present
				} )
			);

			return abilitiesWithCategory;
		} catch ( error ) {
			log.error( 'Error fetching abilities:', error );
			return [];
		}
	};

	return {
		// Provide getAbilities function that filters to big-sky category and client-side only
		getAbilities: wrappedGetAbilities,
	};
}
