/**
 * WordPress dependencies
 */
import { registerPlugin } from '@wordpress/plugins';
import { more } from '@wordpress/icons';

/**
 * Internal dependencies
 */
import './style.scss';
import BigSky from './components/index.js';
import ErrorBoundary from './components/error-boundary.js';
import EditorSubscriptions from '@components/editor-subscriptions';
import useHandleReset from './hooks/use-handle-reset.js';
import useShouldLoadBigSky from './hooks/use-should-load-big-sky.js';

export const AssemblerPlugin = () => {
	const handleReset = useHandleReset();

	const shouldLoadBigSky = useShouldLoadBigSky();

	if ( ! shouldLoadBigSky ) {
		return null;
	}

	return (
		<ErrorBoundary onReset={ handleReset }>
			<BigSky />
			<EditorSubscriptions />
		</ErrorBoundary>
	);
};

registerPlugin( 'big-sky-assembler', {
	icon: more,
	render: AssemblerPlugin,
} );

function disableZoom() {
	let viewport = document.querySelector( 'meta[name="viewport"]' );
	if ( ! viewport ) {
		viewport = document.createElement( 'meta' );
		viewport.name = 'viewport';
		document.head.appendChild( viewport );
	}
	viewport.content =
		'width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no';
}

window.addEventListener( 'DOMContentLoaded', disableZoom );
