// Site metadata field lists
export const allSiteMetadataFields = [
	'siteType',
	'siteFeatures',
	'topic',
	'siteTitle',
	'siteDescription',
	'personality',
	'imageStyle',
	'siteLocationName',
	'colorRequest',
	'requestedPages',
	'storeAddress',
	'siteGoals',
	'keyFacts',
	'primaryCallToAction',
	'avatarUrl',
	'avatarAltText',
	'avatarId',
	'siteEmail',
	'sitePhone',
	'siteLinks',
	'_gravatar_flow',
];

export const requiredSiteMetadataFields = [
	'siteType',
	'topic',
	'siteTitle',
	'siteDescription',
];

/**
 * Get site metadata fields based on requirement type
 * @param {string} type - 'required' | 'all'
 * @return {Array} Array of field names
 */
export const getSiteMetadataFields = ( type = 'all' ) => {
	return type === 'required'
		? requiredSiteMetadataFields
		: allSiteMetadataFields;
};
