/**
 * Internal dependencies
 */
import log from '@utils/log-debug.js';

/**
 * Bumps a WordPress.com stats pixel.
 *
 * @param {string} group
 * @param {string} statName
 */
export default function bumpMcStat( group, statName ) {
	const allowedGroups = [ 'big-sky-onboarding', 'big-sky-test' ];
	if ( ! allowedGroups.includes( group ) ) {
		log.warn( `Invalid stat group: ${ group }` );
		return;
	}

	const allowedStats = [ 'spec-start', 'build-start', 'build-complete' ];
	if ( ! allowedStats.includes( statName ) ) {
		log.warn( `Invalid stat name: ${ statName }` );
		return;
	}

	const pixelUrl = `https://pixel.wp.com/g.gif?v=wpcom-no-pv&x_${ group }=${ statName }`;

	try {
		fetch( pixelUrl, { keepalive: true } );
	} catch ( error ) {
		log.error( `Logging pixel failed for ${ group }=${ statName }`, error );
	}
}
