/**
 * WordPress dependencies
 */
import { serialize } from '@wordpress/blocks';
import {
	dispatch as dataDispatch,
	select as dataSelect,
} from '@wordpress/data';
import { store as coreStore } from '@wordpress/core-data';
import { STORE_NAME as AI_STORE_NAME } from '@store/constants';

/**
 * Process images for pages that were created during site build.
 * Uses cached images from the workflow to populate image blocks.
 *
 * @param {Array}  pages            - Array of page objects with blocks needing image processing
 * @param {number} pages[].pageId   - The page ID
 * @param {Array}  pages[].blocks   - Array of blocks for the page
 * @param {string} pages[].pageName - The page name
 * @return {Promise<Object>} Results with success count and total images processed
 */
export async function processPendingPageImages( pages ) {
	if ( ! pages || pages.length === 0 ) {
		return {
			successCount: 0,
			failCount: 0,
			failedPages: [],
		};
	}

	const cachedContent = dataSelect( AI_STORE_NAME ).getCachedContent();

	// Track which cached images have been used
	let imageIndex = 0;
	let backgroundImageIndex = 0;

	/**
	 * Recursively find and update image/cover blocks with cached images
	 *
	 * @param {Array} blocks - Blocks to process
	 */
	const updateBlocksWithCachedImages = ( blocks ) => {
		blocks.forEach( ( block ) => {
			// Only process core/image and core/cover blocks
			if ( block.name === 'core/image' || block.name === 'core/cover' ) {
				// Don't overwrite the user's avatar with a cached image.
				if ( block.attributes?.metadata?.isUserAvatar ) {
					if ( block.innerBlocks?.length > 0 ) {
						updateBlocksWithCachedImages( block.innerBlocks );
					}
					return;
				}

				const isBackgroundImage = block.name === 'core/cover';
				const cachedImages = isBackgroundImage
					? cachedContent?.backgroundImages || []
					: cachedContent?.images || [];

				if ( cachedImages.length > 0 ) {
					const currentIndex = isBackgroundImage
						? backgroundImageIndex
						: imageIndex;

					// Use modulo to cycle through cached images
					const imageIndexToUse = currentIndex % cachedImages.length;
					const cachedImage = cachedImages[ imageIndexToUse ];

					// Increment the index
					if ( isBackgroundImage ) {
						backgroundImageIndex++;
					} else {
						imageIndex++;
					}

					// Update block attributes directly
					block.attributes = {
						...block.attributes,
						url: cachedImage.url,
						id: cachedImage.id,
						alt: cachedImage.alt || '',
					};
				} else {
					console.warn(
						`⚠️ No cached images available for ${ block.name } blocks`
					);
				}
			}

			// Recursively process inner blocks
			if ( block.innerBlocks?.length > 0 ) {
				updateBlocksWithCachedImages( block.innerBlocks );
			}
		} );
	};

	// Process images for each page
	const imageProcessingPromises = pages.map( async ( pageData ) => {
		try {
			// Walk through blocks and update image/cover blocks with cached images
			updateBlocksWithCachedImages( pageData.blocks );

			// Serialize and save the updated page
			const updatedContent = serialize( pageData.blocks );
			await dataDispatch( coreStore ).saveEntityRecord(
				'postType',
				'page',
				{
					id: pageData.pageId,
					content: updatedContent,
				},
				{ throwOnError: false }
			);

			return {
				success: true,
				pageId: pageData.pageId,
				pageName: pageData.pageName,
			};
		} catch ( error ) {
			console.error(
				`❌ Error processing images for page "${ pageData.pageName }":`,
				error.message
			);
			return {
				success: false,
				pageId: pageData.pageId,
				pageName: pageData.pageName,
				error: error.message,
			};
		}
	} );

	const results = await Promise.all( imageProcessingPromises );

	const successCount = results.filter( ( r ) => r.success ).length;
	const failCount = results.filter( ( r ) => ! r.success ).length;

	const failedPages = [];
	if ( failCount > 0 ) {
		results
			.filter( ( r ) => ! r.success )
			.forEach( ( r ) => {
				const failedPage = `${ r.pageName } (${ r.error })`;
				failedPages.push( failedPage );
			} );
		console.error(
			`❌ Failed to process images for ${ failCount } page(s): ${ failedPages.join(
				', '
			) }`
		);
	}

	return {
		successCount,
		failCount,
		failedPages,
	};
}
