/**
 * WordPress dependencies
 */
import { useCallback, useEffect, useRef } from '@wordpress/element';
import { useDispatch } from '@wordpress/data';
import { store as aiStore } from '@store';

/**
 * Internal dependencies
 */
import log from '@utils/log-debug';
import { validateSpecData } from '@utils/site-spec-validation';
import { fetchSiteSpec } from '@utils/site-spec-api';
import { removeUrlParam } from '@utils/url-params';

/**
 * Custom hook to handle spec processing asynchronously
 * Replaces the inline spec processing logic in onboarding component
 *
 * @param {string} specId - The spec ID to process
 * @return {Object} Processing state and utilities
 */
export default function useSpecProcessor( specId ) {
	const hasProcessedSpec = useRef( false );
	const processingRef = useRef( false );

	const { setBigSkyPendingSpec, setIsProcessingSpec } =
		useDispatch( aiStore );

	const processSpec = useCallback( async () => {
		// Prevent duplicate processing
		if (
			! specId ||
			hasProcessedSpec.current ||
			window.bigSkySpecProcessed ||
			processingRef.current
		) {
			return;
		}

		// Set processing flags
		hasProcessedSpec.current = true;
		window.bigSkySpecProcessed = true;
		processingRef.current = true;

		try {
			// Fetch spec data with retry logic

			setIsProcessingSpec( true );
			const rawSpecData = await fetchSiteSpec( specId );

			if ( ! rawSpecData ) {
				throw new Error(
					'Failed to fetch spec data after all retries'
				);
			}

			// Validate and process the spec data
			const validatedSpecData = validateSpecData( rawSpecData );

			log.info( 'Spec processing completed:', {
				specId,
				hasData: !! validatedSpecData,
			} );

			// Store the spec data for later use when canvas is ready
			setBigSkyPendingSpec( validatedSpecData );
		} catch ( error ) {
			log.error( 'Error processing spec:', {
				specId,
				error: error.message,
				missingFields: error.missingFields || null,
			} );
			// For validation errors, log specific details
			if ( error.missingFields ) {
				log.warn(
					'Spec validation failed - missing required fields:',
					error.missingFields
				);
			}

			// Reset the flags if there was an error so it can be retried
			setIsProcessingSpec( false );
			removeUrlParam( 'spec_id' );
			hasProcessedSpec.current = false;
			window.bigSkySpecProcessed = false;
		} finally {
			processingRef.current = false;
			setIsProcessingSpec( false ); // Reset processing flag once done
		}
	}, [ setBigSkyPendingSpec, setIsProcessingSpec, specId ] );

	// Process spec
	useEffect( () => {
		if (
			specId &&
			! hasProcessedSpec.current &&
			! window.bigSkySpecProcessed
		) {
			processSpec();
		}
	}, [ specId, processSpec ] );

	return {
		hasProcessedSpec: hasProcessedSpec.current,
		isProcessing: processingRef.current,
	};
}
