/**
 * WordPress dependencies
 */
import { createElement } from '@wordpress/element';

/**
 * Internal dependencies
 */
import './inline-suggestions.scss';

/**
 * Simple inline suggestions component that can be embedded in messages
 * Styled to match the empty view suggestions exactly
 *
 * @param {Object} props             - Component props
 * @param {Array}  props.suggestions - Array of suggestion objects with id, label, and prompt
 */
export default function InlineSuggestions( { suggestions = [] } ) {
	if ( ! suggestions || suggestions.length === 0 ) {
		return null;
	}

	const handleClick = ( suggestion ) => {
		if ( suggestion.prompt ) {
			// Dispatch a custom event to set the input value
			// The dock component listens for this event
			const event = new CustomEvent( 'big-sky-inline-suggestion-click', {
				detail: { value: suggestion.prompt },
			} );
			window.dispatchEvent( event );
		}
	};

	return createElement(
		'div',
		{
			className: 'big-sky__inline-suggestions',
		},
		suggestions.map( ( suggestion ) =>
			createElement(
				'button',
				{
					key: suggestion.id,
					className: 'big-sky__inline-suggestion-button',
					onClick: () => handleClick( suggestion ),
					type: 'button',
				},
				suggestion.label
			)
		)
	);
}
