export const messageRoles = {
	SYSTEM: 'system',
	USER: 'user',
	ASSISTANT: 'assistant',
	ACTION: 'action',
	COMPONENT: 'component',
	THINKING: 'thinking',
	ERROR: 'error',
	ERROR_ASSISTANT: 'error_assistant',
	WARNING: 'warning',
	TOOL: 'tool',
	SCREENSHOT: 'screenshot',
	COMMENT: 'comment',
	CHECKPOINT_RESTORE: 'checkpoint_restore',
};

export const isChatMessage = ( message ) =>
	typeof message.content === 'string' &&
	( message.role === messageRoles.USER ||
		message.role === messageRoles.ASSISTANT ||
		message.role === messageRoles.TOOL );

