/**
 * WordPress dependencies
 */
import { store as editorStore } from '@wordpress/editor';
import { Spinner, VisuallyHidden } from '@wordpress/components';

/**
 * External dependencies
 */
import { useCallback, useEffect, useRef, useState } from '@wordpress/element';
import { useDispatch, useSelect } from '@wordpress/data';
import { __, sprintf } from '@wordpress/i18n';
import { store as coreDataStore } from '@wordpress/core-data';

/**
 * Internal dependencies
 */
import { store as aiStore } from '@store';
import { requestJetpackToken } from '@utils/request-jetpack-token';
import { getCurrentPageProperties } from '@utils/tracks.js';
import { recordTracksEvent } from '@utils/tracks';
import log from '@utils/log-debug';
import { errorCodes } from '@utils/constants';
import { useRouting } from '@hooks/use-routing';
import './style.scss';

// Used from src/components/chat/thread/index.js
export const getContactSupportUrl = ( { siteId, siteUrl, sessionId } ) => {
	return `https://wordpress.com/sites?help-center=wapuu&user-message=${ encodeURIComponent(
		`Big Sky Session ID: ${ sessionId }`
	) }&site-id=${ siteId }&site-url=${ siteUrl }`;
};

const getGenericErrorMessage = ( { siteId, siteUrl, sessionId } ) => {
	const supportUrl = getContactSupportUrl( {
		siteId,
		siteUrl,
		sessionId,
	} );

	const errorMessage = sprintf(
		/* translators: %1$s is contact support URL, %2$s is session reference for debugging */
		__(
			'Something went wrong. Please try again or [contact support](%1$s) with reference: %2$s',
			'big-sky'
		),
		supportUrl,
		sessionId
	);
	return errorMessage;
};

export default function SiteSpecLanding() {
	const { setAiStep } = useRouting();
	const containerRef = useRef( null );
	const siteSpecInstanceRef = useRef( null );
	const [ isInitialized, setIsInitialized ] = useState( false );
	const [ hasError, setHasError ] = useState( false );
	const [ errorMessage, setErrorMessage ] = useState( '' );
	const [ siteSpecReady, setSiteSpecReady ] = useState( false );

	const { userLocale } = useSelect( ( select ) => ( {
		userLocale: select( aiStore ).getUserLocale(),
	} ) );

	const { setBigSkyPendingSpec } = useDispatch( aiStore );
	const { switchEditorMode } = useDispatch( editorStore );
	const searchParams = new URLSearchParams( window.location.search );
	const sourceQuery = searchParams.get( 'source' ) || null;
	const referrerQuery = searchParams.get( 'referrer' ) || null;
	const hasReferrer = referrerQuery !== null;

	const supportContext = useSelect(
		( select ) => ( {
			siteId:
				select( coreDataStore ).getSite()?.ID ||
				window?.JP_CONNECTION_INITIAL_STATE?.userConnectionData
					?.currentUser?.blogId ||
				'',
			siteUrl:
				window?.Jetpack_Editor_Initial_State?.siteFragment ||
				window.location.hostname,
		} ),
		[]
	);

	// Auth provider for site-spec - uses same auth as big-sky
	const authProvider = useCallback( async () => {
		try {
			const jetpackToken = await requestJetpackToken();
			return {
				Authorization: `Bearer ${ jetpackToken.token }`,
			};
		} catch ( error ) {
			log.error( 'Failed to get Jetpack token for SiteSpec:', error );
		}
	}, [] );

	// handle spec confirm from site spec
	const handleSpecConfirm = useCallback(
		( specData ) => {
			log.info( 'Spec confirmed by site spec: ', specData );
			switchEditorMode( 'visual' );
			setBigSkyPendingSpec( specData );
		},
		[ setBigSkyPendingSpec, switchEditorMode ]
	);

	// handle spec errors
	const handleError = useCallback(
		( error, sessionId ) => {
			// Bail if site-spec did not send error or sessionId
			if ( ! error || ! sessionId ) {
				return;
			}

			// Bail if error is not a string
			let errorString;
			if ( typeof error === 'string' ) {
				errorString = error;
			} else if ( error instanceof Error && error.message ) {
				errorString = error.message;
			} else {
				return;
			}

			if ( errorString.includes( errorCodes.OPENAI_ERROR ) ) {
				return {
					message: __(
						'Whoops! Our AI is having some issues right now. Please try again later.',
						'big-sky'
					),
					disableInputOnError: false,
				};
			}
			return {
				message: getGenericErrorMessage( {
					...supportContext,
					sessionId,
				} ),
				disableInputOnError: false,
			};
		},
		[ supportContext ]
	);

	// Lazy-load the SiteSpec bundle on mount.
	useEffect( () => {
		if ( siteSpecReady ) return;

		// Already loaded (e.g. a previous mount this session).
		if ( typeof window.SiteSpec !== 'undefined' ) {
			setSiteSpecReady( true );
			return;
		}

		const assets = window.bigSkySiteSpecAssets;
		if ( ! assets?.script ) {
			log.error( 'SiteSpec asset URLs missing; cannot load site-spec.' );
			setHasError( true );
			setErrorMessage(
				__(
					'Failed to start chat interface. Please refresh the page and try again.',
					'big-sky'
				)
			);
			return;
		}

		let cancelled = false;

		// Inject the stylesheet once.
		if (
			assets.style &&
			! document.querySelector( 'link[data-site-spec-styles]' )
		) {
			const link = document.createElement( 'link' );
			link.rel = 'stylesheet';
			link.href = assets.style;
			link.dataset.siteSpecStyles = 'true';
			document.head.appendChild( link );
		}

		// Native dynamic import — resolves immediately if the module is
		// already in the browser's module cache.
		import( /* webpackIgnore: true */ assets.script )
			.then( () => {
				if ( ! cancelled ) {
					setSiteSpecReady( true );
				}
			} )
			.catch( ( error ) => {
				log.error( 'Failed to load SiteSpec bundle:', error );
				if ( ! cancelled ) {
					setHasError( true );
					setErrorMessage(
						__(
							'Failed to start chat interface. Please refresh the page and try again.',
							'big-sky'
						)
					);
				}
			} );

		return () => {
			cancelled = true;
		};
	}, [ siteSpecReady ] );

	// Initialize SiteSpec when ready and container is available
	useEffect( () => {
		if ( ! siteSpecReady || ! containerRef.current || isInitialized ) {
			return;
		}

		( async () => {
			try {
				const config = {
					container: containerRef.current,
					agentId: 'site-spec',
					authProvider,
					onSpecConfirm: handleSpecConfirm,
					locale: userLocale,
					onError: handleError,
					tracking: {
						enabled: true,
						prefix: 'jetpack_big_sky',
						getOverrides: ( event ) => {
							const data = {
								post_type: 'page',
								big_sky_version:
									window?.bigSkyInitialState?.bigSkyVersion ??
									'0',
								session_type: 'paid-user-session',
								...getCurrentPageProperties(),
							};

							if ( event.endsWith( 'onboarding_started' ) ) {
								data.source = sourceQuery;
								data.referrer = referrerQuery;
							}

							return data;
						},
					},
					backButton: {
						enabled:
							hasReferrer && sourceQuery === 'sites-dashboard',
						label: __( 'Back to sites', 'big-sky' ),
					},
					exitButton: {
						enabled: true,
						label: __( 'Skip this step', 'big-sky' ),
						callback: () => {
							recordTracksEvent( 'spec_exit_button_clicked' );
							setAiStep( 'edit' );
						},
					},
				};

				const instance = await window.SiteSpec.init( config );
				siteSpecInstanceRef.current = instance;
				setIsInitialized( true );
			} catch ( error ) {
				log.error( 'Failed to initialize SiteSpec:', error );
				setHasError( true );
				setErrorMessage(
					__(
						'Failed to start chat interface. Please refresh the page and try again.',
						'big-sky'
					)
				);
			}
		} )();
	}, [
		siteSpecReady,
		isInitialized,
		authProvider,
		userLocale,
		handleSpecConfirm,
		sourceQuery,
		referrerQuery,
		hasReferrer,
		handleError,
		setAiStep,
	] );

	// Cleanup on unmount
	useEffect( () => {
		return () => {
			// Destroy SiteSpec instance
			if ( siteSpecInstanceRef.current ) {
				siteSpecInstanceRef.current.destroy();
				siteSpecInstanceRef.current = null;
			}
		};
	}, [] );

	return (
		<div className="site-spec-landing">
			<div
				ref={ containerRef }
				className="site-spec-landing__container"
				aria-label={ __( 'AI Site Builder Chat Interface', 'big-sky' ) }
			>
				{ hasError && (
					<div className="big-sky-onboarding__site-spec-init-error">
						{ errorMessage }
					</div>
				) }
			</div>
			{ ! isInitialized && ! hasError && (
				<div className="site-spec-landing__loading" role="status">
					<Spinner />
					<VisuallyHidden>
						{ __( 'Loading…', 'big-sky' ) }
					</VisuallyHidden>
				</div>
			) }
		</div>
	);
}
