/**
 * Custom action handlers for the Big Sky AI store.
 * Allows Calypso to override specific store actions with custom implementations.
 */

const CUSTOM_ACTIONS_KEY = 'bigSkyCustomActions';

// Share custom actions via the window object so they are accessible across bundles
// For example: calypso-agent-provider and big-sky-plugin
const customActions =
	typeof window !== 'undefined'
		? ( window[ CUSTOM_ACTIONS_KEY ] ??= {} )
		: {};

/**
 * Register custom actions from Calypso.
 *
 * @param {Object.<string, Function>} actions - Map of action names to custom handler functions
 */
export const registerCustomActions = ( actions ) => {
	Object.assign( customActions, actions );
};

/**
 * Get a custom action handler if registered.
 *
 * @param {string} actionName - Name of the action to retrieve
 * @return {Function|null} Custom action handler function, or null if not registered
 */
export const getCustomAction = ( actionName ) => {
	return customActions[ actionName ] || null;
};
