/**
 * WordPress dependencies
 */
import { useSelect } from '@wordpress/data';
import { useCallback } from '@wordpress/element';
import { store as coreStore } from '@wordpress/core-data';

/**
 * External dependencies
 */
import { extend } from 'colord';
import a11yPlugin from 'colord/plugins/a11y';
import { store as aiStore } from '@store';

/**
 * Internal dependencies
 */
import { loadButtonVariations } from '@utils/button-variations';
extend( [ a11yPlugin ] );

export default function useVariations() {
	const { __experimentalGetCurrentThemeGlobalStylesVariations } =
		useSelect( coreStore );
	const themeVariations = useSelect( ( select ) => {
		return select(
			coreStore
		).__experimentalGetCurrentThemeGlobalStylesVariations();
	} );

	const { getGeneratedVariations } = useSelect( aiStore );

	const getColorVariations = useCallback( () => {
		const variations =
			themeVariations ||
			__experimentalGetCurrentThemeGlobalStylesVariations();
		const colorVariations =
			variations?.filter( ( v ) => isColorVariation( v ) ) || [];

		// Inject custom-generated variation so that it's available to the color picker.
		if ( getGeneratedVariations && getGeneratedVariations()?.length > 0 ) {
			return [ ...getGeneratedVariations(), ...colorVariations ];
		}
		return colorVariations;
	}, [
		themeVariations,
		__experimentalGetCurrentThemeGlobalStylesVariations,
		getGeneratedVariations,
	] );

	const getFontVariations = useCallback( () => {
		const variations =
			themeVariations ||
			__experimentalGetCurrentThemeGlobalStylesVariations();

		const fontVariations =
			variations?.filter( ( v ) => isFontVariation( v ) ) || [];

		// Include dynamically generated font variations
		if ( getGeneratedVariations && getGeneratedVariations()?.length > 0 ) {
			// Filter generated variations to only include font variations
			const generatedFontVariations = getGeneratedVariations().filter(
				( v ) => isFontVariation( v )
			);
			if ( generatedFontVariations.length > 0 ) {
				return [ ...generatedFontVariations, ...fontVariations ];
			}
		}

		return fontVariations;
	}, [
		themeVariations,
		__experimentalGetCurrentThemeGlobalStylesVariations,
		getGeneratedVariations,
	] );

	const getColorVariationByTitle = useCallback(
		( title ) => {
			const colors = getColorVariations();
			return colors?.find( ( v ) => v.title === title );
		},
		[ getColorVariations ]
	);

	const getFontVariationByTitle = useCallback(
		( title ) => {
			const fonts = getFontVariations();
			return fonts?.find( ( v ) => v.title === title );
		},
		[ getFontVariations ]
	);

	const isColorVariation = ( variation ) => {
		return variation?.settings?.color && ! variation?.settings?.typography;
	};

	const isFontVariation = ( variation ) => {
		return variation?.settings?.typography && ! variation?.settings?.color;
	};

	const getButtonVariations = useCallback( () => {
		try {
			// Get all button variations using the loadButtonVariations function
			return loadButtonVariations();
		} catch ( error ) {
			throw new Error( 'Error loading button variations' );
		}
	}, [] );

	const getButtonVariationByTitle = useCallback(
		( title ) => {
			const variations = getButtonVariations();
			return variations?.find( ( v ) => v.title === title );
		},
		[ getButtonVariations ]
	);

	return {
		getColorVariations,
		getFontVariations,
		getButtonVariations,
		getButtonVariationByTitle,
		getColorVariationByTitle,
		getFontVariationByTitle,
		isColorVariation,
		isFontVariation,
	};
}
